INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C1','math',2,2,'u3',2,'1 m 알기 — 100 cm가 1 m임을 알고, 1 m를 쓰고 「1 미터」로 읽으며, 몇백 cm와 몇 m를 서로 바꾸기',ARRAY['2수03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C2','math',2,2,'u3',2,'길이를 두 가지로 나타내기 — 몇 cm를 몇 m 몇 cm로 가르고, 몇 m 몇 cm를 몇 cm로 모으며(cm가 한 자리면 0으로 자리 지키기), 단위가 다른 두 길이를 같은 단위로 바꾸어 견주기',ARRAY['2수03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C3','math',2,2,'u3',2,'알맞은 단위 고르기 — 짧은 길이는 cm로, 긴 길이는 m로 나타내면 편함을 알고 상황에 알맞은 단위 고르기',ARRAY['2수03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C4','math',2,2,'u3',3,'줄자로 길이 재기 — 물건에 알맞은 자(곧은자·줄자)를 고르고, 한끝을 눈금 0에 맞추어 다른 끝의 눈금을 읽으며, 잰 길이를 몇 cm와 몇 m 몇 cm로 나타내기',ARRAY['2수03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C5','math',2,2,'u3',4,'길이의 합 — 색 테이프를 이어 붙이는 상황에서 m는 m끼리, cm는 cm끼리 더해 길이의 합을 구하고, 같은 단위끼리 맞추어 세로셈으로 쓰기',ARRAY['2수03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C6','math',2,2,'u3',5,'길이의 차 — 잘라 쓰고 남은 길이·두 도막·두 길이의 차를 m는 m끼리, cm는 cm끼리 빼서 구하고, 구한 차에 뺀 길이를 더해 다시 확인하기',ARRAY['2수03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C7','math',2,2,'u3',6,'1 m를 기준으로 어림하기 — 양팔·뼘·걸음 등 몸의 부분으로 1 m를 재어 보고, 1 m를 기준 삼아 2 m·3 m를 어림하며, 어림한 길이에 「약」을 붙이고 자로 재어 확인하기',ARRAY['2수03-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C8','math',2,2,'u3',7,'긴 거리 어림하기 — 5 m·10 m를 기준 삼거나, 몇 부분으로 나누어 어림한 뒤 더하거나, 같은 간격이 몇 개인지 세어 긴 거리를 어림하기',ARRAY['2수03-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C9','math',2,2,'u3',9,'길이 재기로 문제 해결하기 — 동물 몸길이 사전을 만들며 몸길이를 견주고 합과 차를 구하며, 조사한 길이를 몇 m 몇 cm로 바르게 적기',ARRAY['2수03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X01','math',2,'u3',ARRAY['M2-2-u3-C1','M2-2-u3-C2','M2-2-u3-C4']::text[],'1 m와 100 cm의 관계를 모른다 — 1 m를 10 cm나 1000 cm로 여기거나, 수는 그대로 두고 단위 글자만 바꿔 쓴다(300 cm = 300 m)','1 m 막대에 1 cm가 100번 들어간다 — 100 cm마다 1 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X02','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4']::text[],'몇 m 몇 cm를 몇 cm로 바꿀 때 두 수를 그냥 이어 붙여 0을 빠뜨리거나(3 m 4 cm → 34 cm), m와 cm의 수를 뒤바꾼다','m 자리는 백의 자리 — cm가 한 자리면 십의 자리에 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X03','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4','M2-2-u3-C9']::text[],'몇 cm를 몇 m 몇 cm로 가를 때 자리를 잘못 가른다(248 cm → 24 m 8 cm)','백의 자리 숫자만 m — 뒤의 두 자리는 cm') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X04','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5']::text[],'m의 수와 cm의 수를 더해 버리거나 m와 cm를 한꺼번에 계산한다(5 m 73 cm → 78 cm)','m는 m끼리, cm는 cm끼리 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X05','math',2,'u3',ARRAY['M2-2-u3-C3','M2-2-u3-C9']::text[],'길이에 알맞지 않은 단위를 고르거나 단위를 빠뜨린다(필통 약 15 m, 몸길이 「약 240」)','손에 쥐는 것은 cm, 몸보다 긴 것은 m — 수 뒤에 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X06','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'줄자의 한끝을 0에 맞추지 않거나, 0이 아닌 곳에서 시작했는데 다른 끝의 눈금 숫자를 그대로 길이로 읽는다','한끝을 0에 — 아니면 끝 눈금에서 시작 눈금을 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X07','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'줄자의 눈금을 이웃 눈금으로 잘못 읽는다(140 대신 139·141)','물건 끝에서 줄자까지 선을 내려 긋고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X08','math',2,'u3',ARRAY['M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C9']::text[],'m끼리·cm끼리 계산하면서 한 자리를 잘못 센다(1 m·10 cm 차이)','m 자리, cm 자리를 따로 한 번 더 셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X09','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5','M2-2-u3-C6']::text[],'cm가 한 자리 수일 때 자리를 맞추지 않고 몇십으로 본다(7 m 5 cm의 5를 50처럼 계산)','세로셈에서 cm 수의 일의 자리끼리 줄 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X10','math',2,'u3',ARRAY['M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C9']::text[],'더해야 할 때 빼거나 빼야 할 때 더한다 — 이어 붙인 길이·남은 길이·다른 도막 상황을 거꾸로 읽는다','「이어 붙이면」은 합, 「남은·다른 도막·차」는 차') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X11','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5','M2-2-u3-C6']::text[],'cm의 끝자리 0을 떼고 쓴다(70 cm → 7 cm, 2 m 40 cm → 2 m 4 cm)','cm 자리는 두 자리 — 0도 자리를 지킨다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X12','math',2,'u3',ARRAY['M2-2-u3-C7','M2-2-u3-C8']::text[],'어림한 길이에 「약」을 빼거나, 어림한 길이는 잰 길이와 반드시 같아야 한다고 여긴다','짐작한 길이 앞에는 「약」 — 잰 길이와 조금 달라도 괜찮다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X13','math',2,'u3',ARRAY['M2-2-u3-C7']::text[],'몸의 부분으로 잴 때 단위가 클수록 잰 횟수가 많다고 여기거나, 사람마다 잰 횟수가 같다고 여긴다','큰 걸음은 적게, 작은 뼘은 많이 — 사람마다 크기가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X14','math',2,'u3',ARRAY['M2-2-u3-C7','M2-2-u3-C8']::text[],'기준 길이를 늘려 어림하거나 나누어 어림한 뒤 더할 때 배수·합을 잘못 구한다(약 5 m의 두 배를 약 7 m로, 기준과 횟수를 더함)','기준이 몇 번인지 세어 그만큼 여러 번 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X15','math',2,'u3',ARRAY['M2-2-u3-C8']::text[],'줄 선 사람·놓인 물건의 수와 그 사이 간격의 수를 같다고 여긴다(8명이 1 m 간격 → 8 m)','맨 앞과 맨 뒤 사이의 간격만 세기 — 사람 수보다 하나 적다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X16','math',2,'u3',ARRAY['M2-2-u3-C1','M2-2-u3-C2','M2-2-u3-C3','M2-2-u3-C4','M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C7','M2-2-u3-C8','M2-2-u3-C9']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른, 긴↔짧은','물음의 「아닌·잘못된·짧은」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X17','math',2,'u3',ARRAY['M2-2-u3-C3','M2-2-u3-C7','M2-2-u3-C8']::text[],'길이에 대한 양감이 없어 터무니없는 길이로 어림한다(칠판의 긴 쪽 약 3 cm, 연필 약 1 m)','1 cm는 손톱 너비, 1 m는 양팔 — 떠올려 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X18','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4','M2-2-u3-C7','M2-2-u3-C9']::text[],'단위가 다른 두 길이를 같은 단위로 바꾸지 않고 보이는 수만 견준다(130 cm > 1 m 50 cm)','둘 다 cm로 바꾼 뒤 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X19','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'곧은자와 줄자의 쓰임을 모른다 — 1 m보다 긴 것이나 둥근 것을 곧은자로 재려 하거나 줄자를 구부려 곧은 길이를 잰다','짧고 곧으면 곧은자, 길거나 둥글면 줄자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#1','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','100 cm는 몇 m인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"100 cm는 몇 m인가요?","explanation":["100 cm는 1 m예요.","1 cm가 100번 모이면 100 cm — 이 길이를 1 m라고 해요.","그래서 100 cm = 1 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"options":[{"t":"1 m","correct":true},{"t":"10 m","mis":"M2-2-u3-X01"},{"t":"100 m","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#2','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','1 m를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X05']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"1 m를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 미터","correct":true},{"t":"1 센티미터","mis":"M2-2-u3-X01"},{"t":"1 엠","mis":"M2-2-u3-X05"}],"explanation":["m는 「미터」라고 읽어요.","cm는 「센티미터」라고 읽어요.","그래서 1 m는 「1 미터」예요."],"variant_rule":{"alt":[{"stem":"3 m를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"3 미터","correct":true},{"t":"3 센티미터","mis":"M2-2-u3-X01"},{"t":"3 엠","mis":"M2-2-u3-X05"}],"explanation":["m는 「미터」라고 읽어요.","3 m는 1 m가 3번인 길이예요.","그래서 3 m는 「3 미터」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#3','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'sa','auto','3 m는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"3 m는 몇 cm인가요? 숫자로 쓰세요.","explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번이에요.","그래서 3 m = 300 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"answer":["300"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#4','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',1,'mc','auto','1 m 20 cm는 몇 cm인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X04']::text[],true,'{"seq":4,"concept":"M2-2-u3-C2","difficulty":1,"kind":"mc","stem":"1 m 20 cm는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","100 cm와 20 cm를 모으면 120 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"options":[{"t":"120 cm","correct":true},{"t":"30 cm","mis":"M2-2-u3-X01"},{"t":"21 cm","mis":"M2-2-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#5','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'mc','auto','405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":5,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["405 cm는 400 cm와 5 cm예요.","400 cm는 4 m예요.","그래서 405 cm = 4 m 5 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"4 m 5 cm","correct":true},{"t":"40 m 5 cm","mis":"M2-2-u3-X03"},{"t":"4 m 50 cm","mis":"M2-2-u3-X09"},{"t":"5 m 4 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#6','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'sa','auto','5 m 73 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u3-C2","difficulty":2,"kind":"sa","stem":"5 m 73 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["5 m는 500 cm예요.","500 cm와 73 cm를 모으면 573 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["573"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#7','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C3',2,'mc','auto','교실 문의 높이는 약 2 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],true,'{"seq":7,"concept":"M2-2-u3-C3","difficulty":2,"kind":"mc","stem":"교실 문의 높이는 약 2 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["교실 문은 어른 키보다 높아요.","약 2 cm는 손톱 두 개만큼이라 너무 짧아요.","그래서 교실 문의 높이는 약 2 m예요."],"variant_rule":{"alt":[{"stem":"필통의 길이는 약 15 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["필통은 손에 쥘 만큼 짧아요.","약 15 m는 교실 두 칸만큼이라 너무 길어요.","그래서 필통의 길이는 약 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#8','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'match','auto','같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u3-C2","difficulty":2,"kind":"match","stem":"같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.","pairs":[{"l":"130 cm","r":"1 m 30 cm"},{"l":"305 cm","r":"3 m 5 cm"},{"l":"250 cm","r":"2 m 50 cm"}],"mis":"M2-2-u3-X03","explanation":["130 cm = 100 cm + 30 cm = 1 m 30 cm예요.","305 cm = 300 cm + 5 cm = 3 m 5 cm예요.","250 cm = 200 cm + 50 cm = 2 m 50 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.","pairs":[{"l":"160 cm","r":"1 m 60 cm"},{"l":"408 cm","r":"4 m 8 cm"},{"l":"520 cm","r":"5 m 20 cm"}],"explanation":["160 cm = 100 cm + 60 cm = 1 m 60 cm예요.","408 cm = 400 cm + 8 cm = 4 m 8 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#9','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'ox','auto','248 cm는 24 m 8 cm와 같은 길이예요.',ARRAY['M2-2-u3-X03']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"ox","stem":"248 cm는 24 m 8 cm와 같은 길이예요.","answer":"X","reason_options":[{"t":"248 cm는 200 cm와 48 cm라서 2 m 48 cm니까","correct":true},{"t":"앞의 두 숫자를 m로 읽으면 되니까","mis":"M2-2-u3-X03"}],"mis":"M2-2-u3-X03","explanation":["248 cm = 200 cm + 48 cm예요.","200 cm는 2 m예요.","그래서 248 cm = 2 m 48 cm — 24 m 8 cm가 아니에요."],"variant_rule":{"alt":[{"stem":"365 cm는 3 m 65 cm와 같은 길이예요.","answer":"O","reason_options":[{"t":"365 cm는 300 cm와 65 cm라서 3 m 65 cm니까","correct":true},{"t":"앞의 두 숫자를 m로 읽어 36 m 5 cm니까","mis":"M2-2-u3-X03"}],"explanation":["365 cm = 300 cm + 65 cm예요.","300 cm는 3 m예요.","그래서 365 cm = 3 m 65 cm로 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#10','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',3,'error','auto','5 m 6 cm를 몇 cm로 나타냈어요. 잘못 나타낸 친구는 누구인가요?',ARRAY['M2-2-u3-X02','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C2","difficulty":3,"kind":"error","stem":"5 m 6 cm를 몇 cm로 나타냈어요. 잘못 나타낸 친구는 누구인가요?","options":[{"t":"지우 — 「5와 6을 이어서 56 cm야.」","correct":true,"mis_target":"M2-2-u3-X02"},{"t":"서아 — 「500 cm와 6 cm를 모으면 506 cm야.」","mis":"M2-2-u3-X16"},{"t":"하루 — 「cm가 한 자리라 0을 넣어 506 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["5 m는 500 cm예요.","500 cm와 6 cm를 모으면 506 cm예요.","지우는 0을 빠뜨리고 이어 붙였어요 — 56 cm는 1 m도 안 돼요."],"variant_rule":{"alt":[{"stem":"7 m 3 cm를 몇 cm로 나타냈어요. 잘못 나타낸 친구는 누구인가요?","options":[{"t":"도윤 — 「7과 3을 이어서 73 cm야.」","correct":true,"mis_target":"M2-2-u3-X02"},{"t":"은솔 — 「700 cm와 3 cm를 모으면 703 cm야.」","mis":"M2-2-u3-X16"},{"t":"예린 — 「cm가 한 자리라 0을 넣어 703 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["7 m는 700 cm예요.","700 cm와 3 cm를 모으면 703 cm예요.","도윤이는 0을 빠뜨리고 이어 붙였어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#1','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',2,'mc','auto','730 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],true,'{"seq":1,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"730 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["730 cm는 700 cm와 30 cm예요.","700 cm는 7 m예요.","그래서 730 cm = 7 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"7 m 30 cm","correct":true},{"t":"73 m","mis":"M2-2-u3-X03"},{"t":"7 m 3 cm","mis":"M2-2-u3-X11"},{"t":"30 m 7 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#2','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C1',2,'mc','auto','600 cm는 몇 m인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":2,"kind":"mc","stem":"600 cm는 몇 m인가요?","explanation":["100 cm는 1 m예요.","600 cm는 100 cm가 6번이에요.","그래서 600 cm = 6 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"options":[{"t":"6 m","correct":true},{"t":"60 m","mis":"M2-2-u3-X01"},{"t":"600 m","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#3','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#4','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','길이가 가장 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18']::text[],false,'{"seq":4,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"길이가 가장 긴 것은 어느 것인가요?","options":[{"t":"3 m 5 cm","correct":true},{"t":"298 cm","mis":"M2-2-u3-X18"},{"t":"2 m 99 cm","mis":"M2-2-u3-X18"},{"t":"300 cm","mis":"M2-2-u3-X18"}],"explanation":["모두 cm로 바꾸면 305 cm, 298 cm, 299 cm, 300 cm예요.","305 cm가 가장 길어요.","그래서 3 m 5 cm가 가장 길어요 — 보이는 수 298만 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#5','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C3',3,'mc','auto','cm보다 m로 나타내기에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":5,"concept":"M2-2-u3-C3","difficulty":3,"kind":"mc","stem":"cm보다 m로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"운동장의 긴 쪽의 길이","correct":true},{"t":"연필의 길이","mis":"M2-2-u3-X05"},{"t":"지우개의 길이","mis":"M2-2-u3-X05"},{"t":"공책의 짧은 쪽의 길이","mis":"M2-2-u3-X05"}],"explanation":["m는 1 m보다 긴 길이를 나타내기 편해요.","연필·지우개·공책은 1 m보다 훨씬 짧아 cm가 알맞아요.","운동장의 긴 쪽은 아주 길어서 m로 나타내면 편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#6','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','6 m 8 cm = □ cm에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X02','M2-2-u3-X09','M2-2-u3-X04']::text[],false,'{"seq":6,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"6 m 8 cm = □ cm에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"608","correct":true},{"t":"68","mis":"M2-2-u3-X02"},{"t":"680","mis":"M2-2-u3-X09"},{"t":"14","mis":"M2-2-u3-X04"}],"explanation":["6 m는 600 cm예요.","600 cm와 8 cm를 모으면 608 cm예요.","cm가 한 자리 수라 십의 자리에 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#7','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C1',3,'error','auto','1 m에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X16']::text[],false,'{"seq":7,"concept":"M2-2-u3-C1","difficulty":3,"kind":"error","stem":"1 m에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「1 m는 10 cm와 같아.」","correct":true,"mis_target":"M2-2-u3-X01"},{"t":"아린 — 「1 m는 100 cm와 같아.」","mis":"M2-2-u3-X16"},{"t":"지안 — 「1 m는 1 cm가 100번이야.」","mis":"M2-2-u3-X16"}],"explanation":["1 cm가 100번이면 100 cm예요.","100 cm는 1 m와 같아요.","태민이는 1 m를 10 cm로 잘못 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#8','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',4,'essay','teacher','352 cm를 「몇 m 몇 cm」로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C2","difficulty":4,"kind":"essay","stem":"352 cm를 「몇 m 몇 cm」로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 352 cm는 300 cm와 52 cm로 가를 수 있다. 300 cm는 3 m이므로 352 cm = 3 m 52 cm이다.","scoring_points":["352 cm를 300 cm와 52 cm로 갈랐는가","300 cm가 3 m임을 썼는가","3 m 52 cm라고 바르게 나타냈는가"]},"explanation":["352 cm를 100 cm씩 묶음과 나머지로 갈라요.","300 cm는 3 m예요.","그래서 352 cm = 3 m 52 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#9','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C3',4,'essay','teacher','교실 문의 높이와 필통의 길이를 나타낼 때 각각 알맞은 단위를 고르고, 그렇게 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C3","difficulty":4,"kind":"essay","stem":"교실 문의 높이와 필통의 길이를 나타낼 때 각각 알맞은 단위를 고르고, 그렇게 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 교실 문의 높이는 m가 알맞다. 1 m보다 훨씬 길어서 cm로 나타내면 수가 커지기 때문이다. 필통의 길이는 cm가 알맞다. 1 m보다 짧기 때문이다.","scoring_points":["교실 문의 높이에 m를 골랐는가","필통의 길이에 cm를 골랐는가","길이가 1 m보다 긴지 짧은지로 까닭을 썼는가"]},"explanation":["긴 길이를 cm로 나타내면 수가 너무 커요.","짧은 길이는 cm로 나타내야 정확해요.","길이에 따라 알맞은 단위를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#10','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',4,'mc','auto','가 2 m 7 cm, 나 270 cm, 다 2 m 17 cm예요. 짧은 것부터 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":10,"concept":"M2-2-u3-C2","difficulty":4,"kind":"mc","stem":"가 2 m 7 cm, 나 270 cm, 다 2 m 17 cm예요. 짧은 것부터 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"가, 다, 나","correct":true},{"t":"가, 나, 다","mis":"M2-2-u3-X18"},{"t":"나, 가, 다","mis":"M2-2-u3-X18"},{"t":"다, 나, 가","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 가 207 cm, 나 270 cm, 다 217 cm예요.","207 < 217 < 270이에요.","그래서 짧은 것부터 가, 다, 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#1','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','줄자로 길이를 재는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X19']::text[],true,'{"seq":1,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"줄자로 길이를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건의 한끝을 줄자의 눈금 0에 맞춰요","correct":true},{"t":"물건의 한끝을 눈금 1에 맞춰요","mis":"M2-2-u3-X06"},{"t":"줄자를 구부려서 재요","mis":"M2-2-u3-X19"}],"explanation":["한끝을 눈금 0에 맞추어야 다른 끝의 눈금이 곧 길이가 돼요.","눈금 1에 맞추면 1 cm만큼 길게 읽어요.","곧은 길이는 줄자를 곧게 펴서 재요."],"variant_rule":{"alt":[{"stem":"줄자로 책장의 길이를 재요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"책장의 한끝을 줄자의 눈금 0에 맞춰요","correct":true},{"t":"책장의 가운데에 줄자를 대요","mis":"M2-2-u3-X06"},{"t":"줄자를 둥글게 말아 대요","mis":"M2-2-u3-X19"}],"explanation":["먼저 한끝을 눈금 0에 맞춰요.","그다음 다른 끝이 닿은 눈금을 읽어요.","줄자는 곧게 펴서 대요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#2','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'sa','auto','책상의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"책상의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 140이니 140 cm예요.","140 cm는 1 m 40 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["140"],"asset":{"type":"tape","len":140,"label":"책상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#3','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 130이니 130 cm예요.","130 cm = 100 cm + 30 cm = 1 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"1 m 30 cm","correct":true},{"t":"13 m","mis":"M2-2-u3-X03"},{"t":"1 m 31 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":130,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#4','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'ox','auto','둥근 나무의 둘레는 줄자로 재면 좋아요.',ARRAY['M2-2-u3-X19']::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"ox","stem":"둥근 나무의 둘레는 줄자로 재면 좋아요.","answer":"O","reason_options":[{"t":"줄자는 휘어져서 둥근 곳도 감아 잴 수 있으니까","correct":true},{"t":"둥근 것은 곧은자로만 잴 수 있으니까","mis":"M2-2-u3-X19"}],"mis":"M2-2-u3-X19","explanation":["줄자는 부드럽게 휘어요.","그래서 둥근 나무의 둘레에 감아 잴 수 있어요.","곧은자는 휘지 않아 둘레를 재기 어려워요."],"variant_rule":{"alt":[{"stem":"교실의 긴 쪽은 15 cm 곧은자로 재면 좋아요.","answer":"X","reason_options":[{"t":"교실의 긴 쪽은 1 m보다 훨씬 길어서 줄자가 알맞으니까","correct":true},{"t":"곧은자는 무엇이든 잴 수 있으니까","mis":"M2-2-u3-X19"}],"explanation":["교실의 긴 쪽은 몇 m나 돼요.","15 cm 곧은자로는 수십 번 옮겨 대야 해요.","긴 길이는 줄자로 재는 것이 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#5','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":5,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["사물함의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#6','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'sa','auto','매트의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"매트의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["매트의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 187이니 187 cm예요.","187 cm는 1 m 87 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["187"],"asset":{"type":"tape","len":187,"label":"매트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#7','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":7,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?","explanation":["탁자의 한끝은 눈금 2, 다른 끝은 눈금 120에 있어요.","120 − 2 = 118이니 118 cm예요.","끝 눈금 120을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"118 cm","correct":true},{"t":"120 cm","mis":"M2-2-u3-X06"},{"t":"119 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":118,"label":"탁자","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#8','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'match','auto','멀리 던지기에서 잰 거리를 「몇 m 몇 cm」로 나타낸 것과 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u3-C4","difficulty":2,"kind":"match","stem":"멀리 던지기에서 잰 거리를 「몇 m 몇 cm」로 나타낸 것과 이으세요.","pairs":[{"l":"210 cm","r":"2 m 10 cm"},{"l":"350 cm","r":"3 m 50 cm"},{"l":"430 cm","r":"4 m 30 cm"}],"mis":"M2-2-u3-X03","explanation":["210 cm = 200 cm + 10 cm = 2 m 10 cm예요.","350 cm = 300 cm + 50 cm = 3 m 50 cm예요.","430 cm = 400 cm + 30 cm = 4 m 30 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 멀리 던지기에서 잰 거리를 「몇 m 몇 cm」로 나타낸 것과 이으세요.","pairs":[{"l":"190 cm","r":"1 m 90 cm"},{"l":"305 cm","r":"3 m 5 cm"},{"l":"260 cm","r":"2 m 60 cm"}],"explanation":["190 cm = 100 cm + 90 cm = 1 m 90 cm예요.","305 cm = 300 cm + 5 cm = 3 m 5 cm예요.","260 cm = 200 cm + 60 cm = 2 m 60 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#9','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','교실의 긴 쪽의 길이를 재려고 해요. 어느 자로 재면 좋을까요?',ARRAY['M2-2-u3-X19']::text[],true,'{"seq":9,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"교실의 긴 쪽의 길이를 재려고 해요. 어느 자로 재면 좋을까요?","options":[{"t":"줄자","correct":true},{"t":"15 cm 곧은자","mis":"M2-2-u3-X19"},{"t":"30 cm 곧은자","mis":"M2-2-u3-X19"}],"explanation":["교실의 긴 쪽은 1 m보다 훨씬 길어요.","곧은자는 짧아서 여러 번 옮겨 대야 해요.","긴 길이는 줄자로 한 번에 재요."],"variant_rule":{"alt":[{"stem":"지우개의 길이를 재려고 해요. 어느 자로 재면 좋을까요?","options":[{"t":"15 cm 곧은자","correct":true},{"t":"10 m 줄자","mis":"M2-2-u3-X19"},{"t":"운동장 줄자","mis":"M2-2-u3-X19"}],"explanation":["지우개는 짧고 곧아요.","짧고 곧은 물건은 곧은자로 재기 좋아요.","긴 줄자는 펴고 감기 번거로워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#10','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',3,'error','auto','줄자로 막대의 길이를 재었어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":3,"kind":"error","stem":"줄자로 막대의 길이를 재었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「끝 눈금이 122니까 막대는 122 cm야.」","correct":true,"mis_target":"M2-2-u3-X06"},{"t":"서아 — 「2부터 122까지니까 120 cm야.」","mis":"M2-2-u3-X16"},{"t":"하루 — 「120 cm는 1 m 20 cm라고도 해.」","mis":"M2-2-u3-X16"}],"explanation":["막대의 한끝이 눈금 0이 아니라 2에 있어요.","122 − 2 = 120이니 막대는 120 cm예요.","지우는 끝 눈금을 그대로 읽었어요."],"asset":{"type":"tape","len":120,"label":"막대","s":2},"variant_rule":{"alt":[{"stem":"줄자로 끈의 길이를 재었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「끝 눈금이 138이니까 끈은 138 cm야.」","correct":true,"mis_target":"M2-2-u3-X06"},{"t":"은솔 — 「3부터 138까지니까 135 cm야.」","mis":"M2-2-u3-X16"},{"t":"예린 — 「135 cm는 1 m 35 cm라고도 해.」","mis":"M2-2-u3-X16"}],"explanation":["끈의 한끝이 눈금 0이 아니라 3에 있어요.","138 − 3 = 135이니 끈은 135 cm예요.","도윤이는 끝 눈금을 그대로 읽었어요."],"asset":{"type":"tape","len":135,"label":"끈","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#1','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',2,'mc','auto','현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07','M2-2-u3-X09']::text[],true,'{"seq":1,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["현수막의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 209이니 209 cm예요.","209 cm = 200 cm + 9 cm = 2 m 9 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"2 m 9 cm","correct":true},{"t":"20 m 9 cm","mis":"M2-2-u3-X03"},{"t":"2 m 10 cm","mis":"M2-2-u3-X07"},{"t":"2 m 90 cm","mis":"M2-2-u3-X09"}],"asset":{"type":"tape","len":209,"label":"현수막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#2','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',2,'sa','auto','소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["소파의 한끝은 눈금 3, 다른 끝은 눈금 149에 있어요.","149 − 3 = 146이니 146 cm예요.","끝 눈금 149를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"answer":["146"],"asset":{"type":"tape","len":146,"label":"소파","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#3','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','멀리 던지기에서 제기를 던진 거리를 재는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X19','M2-2-u3-X06']::text[],false,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"멀리 던지기에서 제기를 던진 거리를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"출발선에서 제기가 바닥에 떨어진 곳까지 곧게 재요","correct":true},{"t":"제기가 날아간 길을 따라 구불구불하게 재요","mis":"M2-2-u3-X19"},{"t":"던진 사람의 발끝에서 아무 곳까지 재요","mis":"M2-2-u3-X06"}],"explanation":["거리는 출발선에서 시작해요.","제기가 처음 바닥에 떨어진 곳까지 재요.","거리는 반드시 곧게 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#4','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','줄자로 잰 사물함의 길이가 520 cm예요. 이 길이를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X01']::text[],false,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"줄자로 잰 사물함의 길이가 520 cm예요. 이 길이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 2 cm","mis":"M2-2-u3-X11"},{"t":"50 m 20 cm","mis":"M2-2-u3-X01"}],"explanation":["520 cm = 500 cm + 20 cm예요.","500 cm는 5 m예요.","그래서 520 cm = 5 m 20 cm예요 — 20의 0을 떼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#5','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','칠판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07','M2-2-u3-X09']::text[],true,'{"seq":5,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"칠판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["칠판의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 304이니 304 cm예요.","304 cm = 300 cm + 4 cm = 3 m 4 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"3 m 4 cm","correct":true},{"t":"30 m 4 cm","mis":"M2-2-u3-X03"},{"t":"3 m 5 cm","mis":"M2-2-u3-X07"},{"t":"3 m 40 cm","mis":"M2-2-u3-X09"}],"asset":{"type":"tape","len":304,"label":"칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#6','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','같은 책상을 지아는 140 cm, 세미는 1 m 40 cm라고 했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X18']::text[],false,'{"seq":6,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"같은 책상을 지아는 140 cm, 세미는 1 m 40 cm라고 했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요 — 140 cm와 1 m 40 cm는 같은 길이예요","correct":true},{"t":"지아만 맞아요 — 줄자는 cm로만 읽으니까","mis":"M2-2-u3-X01"},{"t":"세미만 맞아요 — 수가 더 작으니까","mis":"M2-2-u3-X18"}],"explanation":["140 cm = 100 cm + 40 cm예요.","100 cm는 1 m라서 140 cm = 1 m 40 cm예요.","같은 길이를 두 가지 방법으로 나타낸 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#7','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','길이가 1 m보다 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"길이가 1 m보다 긴 것은 어느 것인가요?","options":[{"t":"교실 문의 높이","correct":true},{"t":"필통의 길이","mis":"M2-2-u3-X17"},{"t":"연필의 길이","mis":"M2-2-u3-X17"},{"t":"공책의 긴 쪽의 길이","mis":"M2-2-u3-X17"}],"explanation":["1 m는 양팔을 벌린 길이쯤이에요.","필통·연필·공책은 1 m보다 훨씬 짧아요.","교실 문의 높이는 약 2 m라 1 m보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#8','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'essay','teacher','줄자로 사물함의 길이를 재는 방법을 차례로 설명하고, 잰 길이 520 cm를 두 가지 방법으로 나타내 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C4","difficulty":4,"kind":"essay","stem":"줄자로 사물함의 길이를 재는 방법을 차례로 설명하고, 잰 길이 520 cm를 두 가지 방법으로 나타내 보세요.","answer_guide":{"answer":"예: 사물함의 한끝을 줄자의 눈금 0에 맞춘다. 줄자를 곧게 펴서 다른 끝이 닿은 눈금을 읽는다. 520 cm는 5 m 20 cm라고도 나타낸다.","scoring_points":["한끝을 눈금 0에 맞춘다고 썼는가","다른 끝의 눈금을 읽는다고 썼는가","520 cm = 5 m 20 cm로 나타냈는가"]},"explanation":["한끝을 눈금 0에 맞춰요.","다른 끝이 닿은 눈금 520을 읽어요.","520 cm = 5 m 20 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#9','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'essay','teacher','세미는 줄자로 막대를 재고 128 cm라고 했어요. 무엇이 잘못되었는지 설명하고, 막대의 바른 길이를 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C4","difficulty":4,"kind":"essay","stem":"세미는 줄자로 막대를 재고 128 cm라고 했어요. 무엇이 잘못되었는지 설명하고, 막대의 바른 길이를 구해 보세요.","answer_guide":{"answer":"예: 막대의 한끝이 눈금 0이 아니라 3에 있는데 끝 눈금 128을 그대로 읽었다. 128 − 3 = 125이므로 막대의 길이는 125 cm(1 m 25 cm)이다.","scoring_points":["한끝이 0에 있지 않다는 점을 찾았는가","128 − 3을 계산했는가","125 cm라고 바르게 구했는가"]},"explanation":["한끝이 눈금 3에 있어요.","128 − 3 = 125예요.","막대는 125 cm = 1 m 25 cm예요."],"asset":{"type":"tape","len":125,"label":"막대","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#10','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'mc','auto','슬기는 제기를 2 m 10 cm, 배드민턴공을 3 m 50 cm 던졌어요. 수찬이는 공을 290 cm 던졌어요. 멀리 던진 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":4,"kind":"mc","stem":"슬기는 제기를 2 m 10 cm, 배드민턴공을 3 m 50 cm 던졌어요. 수찬이는 공을 290 cm 던졌어요. 멀리 던진 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"배드민턴공, 수찬이의 공, 제기","correct":true},{"t":"수찬이의 공, 배드민턴공, 제기","mis":"M2-2-u3-X18"},{"t":"제기, 수찬이의 공, 배드민턴공","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 제기 210 cm, 배드민턴공 350 cm, 수찬이의 공 290 cm예요.","350 > 290 > 210이에요.","그래서 배드민턴공, 수찬이의 공, 제기 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#1','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'mc','auto','3 m 40 cm + 5 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":1,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 40 cm + 5 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 40 + 50 = 90.","그래서 3 m 40 cm + 5 m 50 cm = 8 m 90 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"8 m 90 cm","correct":true},{"t":"2 m 10 cm","mis":"M2-2-u3-X10"},{"t":"8 m 9 cm","mis":"M2-2-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#2','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C5","difficulty":1,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 4 + 1 = 5.","cm는 cm끼리 더해요 — 26 + 60 = 86.","그래서 4 m 26 cm + 1 m 60 cm = 5 m 86 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc","calc":"cm"}},"answer":["86"],"asset":{"type":"mcm_calc","a":[4,26],"b":[1,60],"op":"+","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#3','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'sa','auto','세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C5","difficulty":1,"kind":"sa","stem":"세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 2 + 7 = 9.","cm는 cm끼리 더해요 — 24 + 5 = 29.","그래서 2 m 24 cm + 7 m 5 cm = 9 m 29 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc","calc":"m"}},"answer":["9"],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"m"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#4','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'ox','auto','길이의 합을 구할 때는 m는 m끼리, cm는 cm끼리 더해요.',ARRAY['M2-2-u3-X04']::text[],true,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"ox","stem":"길이의 합을 구할 때는 m는 m끼리, cm는 cm끼리 더해요.","answer":"O","reason_options":[{"t":"같은 단위끼리 맞추어 더해야 하니까","correct":true},{"t":"m와 cm의 수를 모두 한꺼번에 더해도 되니까","mis":"M2-2-u3-X04"}],"mis":"M2-2-u3-X04","explanation":["m와 cm는 단위가 달라요.","그래서 같은 단위끼리 맞추어 써요.","m는 m끼리, cm는 cm끼리 더해요."],"variant_rule":{"alt":[{"stem":"1 m 70 cm + 1 m 20 cm를 구할 때 1 + 70 + 1 + 20을 계산하면 돼요.","answer":"X","reason_options":[{"t":"m는 m끼리, cm는 cm끼리 따로 더해야 하니까","correct":true},{"t":"수를 모두 더하면 길이의 합이 되니까","mis":"M2-2-u3-X04"}],"explanation":["1 m + 1 m = 2 m예요.","70 cm + 20 cm = 90 cm예요.","그래서 2 m 90 cm — 수를 한꺼번에 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#5','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 7 = 12.","cm는 cm끼리 더해요 — 35 + 40 = 75.","그래서 5 m 35 cm + 7 m 40 cm = 12 m 75 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"12 m 75 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"13 m 75 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#6','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','색 테이프 두 장을 겹치지 않게 이어 붙였어요. 이은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"색 테이프 두 장을 겹치지 않게 이어 붙였어요. 이은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 더해요 — 2 + 1 = 3.","cm는 cm끼리 더해요 — 45 + 32 = 77.","그래서 2 m 45 cm + 1 m 32 cm = 3 m 77 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"tape"}},"options":[{"t":"3 m 77 cm","correct":true},{"t":"1 m 13 cm","mis":"M2-2-u3-X10"},{"t":"4 m 77 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[2,45],[1,32]],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#7','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 11 + 7 = 18.","cm는 cm끼리 더해요 — 35 + 23 = 58.","그래서 11 m 35 cm + 7 m 23 cm = 18 m 58 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"18 m 58 cm","correct":true},{"t":"4 m 12 cm","mis":"M2-2-u3-X10"},{"t":"19 m 58 cm","mis":"M2-2-u3-X08"},{"t":"18 m 68 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[11,35],"b":[7,23],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#8','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'error','auto','어떤 친구가 2 m 30 cm + 1 m 40 cm를 이렇게 계산했어요. 잘못 계산한 곳은 어디인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08','M2-2-u3-X10']::text[],true,'{"seq":8,"concept":"M2-2-u3-C5","difficulty":2,"kind":"error","stem":"어떤 친구가 2 m 30 cm + 1 m 40 cm를 이렇게 계산했어요. 잘못 계산한 곳은 어디인가요?","options":[{"t":"cm끼리 더한 70을 7이라고 썼어요","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"m끼리 더한 것이 틀렸어요","mis":"M2-2-u3-X08"},{"t":"더해야 하는데 뺐어요","mis":"M2-2-u3-X10"}],"explanation":["m끼리 2 + 1 = 3, cm끼리 30 + 40 = 70이에요.","바른 답은 3 m 70 cm예요.","70의 0을 떼고 7 cm로 쓰면 안 돼요."],"asset":{"type":"mcm_calc","a":[2,30],"b":[1,40],"op":"+","ask":"both","said":[3,7]},"variant_rule":{"alt":[{"stem":"어떤 친구가 3 m 50 cm + 2 m 20 cm를 이렇게 계산했어요. 잘못 계산한 곳은 어디인가요?","options":[{"t":"cm끼리 더한 70을 7이라고 썼어요","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"m끼리 더한 것이 틀렸어요","mis":"M2-2-u3-X08"},{"t":"더해야 하는데 뺐어요","mis":"M2-2-u3-X10"}],"explanation":["m끼리 3 + 2 = 5, cm끼리 50 + 20 = 70이에요.","바른 답은 5 m 70 cm예요.","70의 0을 떼고 7 cm로 쓰면 안 돼요."],"asset":{"type":"mcm_calc","a":[3,50],"b":[2,20],"op":"+","ask":"both","said":[5,7]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#9','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','3 m 52 cm + 4 m 6 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":9,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"3 m 52 cm + 4 m 6 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 4 = 7.","cm는 cm끼리 더해요 — 52 + 6 = 58.","그래서 3 m 52 cm + 4 m 6 cm = 7 m 58 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"7 m 58 cm","correct":true},{"t":"1 m 46 cm","mis":"M2-2-u3-X10"},{"t":"8 m 58 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#10','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',3,'mc','auto','표지판을 만들려고 가로 나무 1 m 70 cm와 세로 나무 1 m 20 cm를 이어요. 필요한 나무는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":10,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"표지판을 만들려고 가로 나무 1 m 70 cm와 세로 나무 1 m 20 cm를 이어요. 필요한 나무는 모두 얼마인가요?","options":[{"t":"2 m 90 cm","correct":true},{"t":"50 cm","mis":"M2-2-u3-X10"},{"t":"2 m 9 cm","mis":"M2-2-u3-X11"}],"explanation":["필요한 나무는 두 나무의 길이의 합이에요.","m끼리 1 + 1 = 2, cm끼리 70 + 20 = 90이에요.","그래서 2 m 90 cm가 필요해요."],"variant_rule":{"alt":[{"stem":"의자를 만들려고 나무 1 m 40 cm와 2 m 30 cm를 이어요. 필요한 나무는 모두 얼마인가요?","options":[{"t":"3 m 70 cm","correct":true},{"t":"1 m 10 cm","mis":"M2-2-u3-X10"},{"t":"3 m 7 cm","mis":"M2-2-u3-X11"}],"explanation":["필요한 나무는 두 나무의 길이의 합이에요.","m끼리 1 + 2 = 3, cm끼리 40 + 30 = 70이에요.","그래서 3 m 70 cm가 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#1','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',2,'mc','auto','6 m 52 cm인 나무와 2 m 7 cm인 나무를 겹치지 않게 이었어요. 이은 나무의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":1,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"6 m 52 cm인 나무와 2 m 7 cm인 나무를 겹치지 않게 이었어요. 이은 나무의 길이는 얼마인가요?","explanation":["m는 m끼리 더해요 — 6 + 2 = 8.","cm는 cm끼리 더해요 — 52 + 7 = 59.","그래서 6 m 52 cm + 2 m 7 cm = 8 m 59 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"join"}},"options":[{"t":"8 m 59 cm","correct":true},{"t":"4 m 45 cm","mis":"M2-2-u3-X10"},{"t":"9 m 59 cm","mis":"M2-2-u3-X08"},{"t":"8 m 69 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#2','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',2,'mc','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":2,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요?","explanation":["m는 m끼리 더해요 — 4 + 2 = 6.","cm는 cm끼리 더해요 — 35 + 43 = 78.","그래서 4 m 35 cm + 2 m 43 cm = 6 m 78 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc","calc":"cm"}},"options":[{"t":"78","correct":true},{"t":"8","mis":"M2-2-u3-X10"},{"t":"88","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[4,35],"b":[2,43],"op":"+","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#3','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','3 m 25 cm + □ m 42 cm = 7 m 67 cm에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":3,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"3 m 25 cm + □ m 42 cm = 7 m 67 cm에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"4","correct":true},{"t":"10","mis":"M2-2-u3-X10"},{"t":"3","mis":"M2-2-u3-X08"}],"explanation":["cm끼리 25 + 42 = 67로 맞아요.","m끼리 3 + □ = 7이에요.","7 − 3 = 4이니 □는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#4','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','두 길이의 합이 5 m 80 cm인 것은 어느 것인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 길이의 합이 5 m 80 cm인 것은 어느 것인가요?","options":[{"t":"2 m 50 cm와 3 m 30 cm","correct":true},{"t":"2 m 50 cm와 3 m 3 cm","mis":"M2-2-u3-X09"},{"t":"3 m 50 cm와 2 m 50 cm","mis":"M2-2-u3-X08"},{"t":"2 m 30 cm와 3 m 30 cm","mis":"M2-2-u3-X08"}],"explanation":["2 m 50 cm + 3 m 30 cm에서 m끼리 5, cm끼리 80이에요.","2 m 50 cm + 3 m 3 cm는 5 m 53 cm예요.","그래서 2 m 50 cm와 3 m 30 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#5','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','색 테이프 세 장 1 m 20 cm, 2 m 35 cm, 3 m 4 cm를 겹치지 않게 이었어요. 이은 길이는 얼마인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"색 테이프 세 장 1 m 20 cm, 2 m 35 cm, 3 m 4 cm를 겹치지 않게 이었어요. 이은 길이는 얼마인가요?","options":[{"t":"6 m 59 cm","correct":true},{"t":"6 m 95 cm","mis":"M2-2-u3-X09"},{"t":"5 m 59 cm","mis":"M2-2-u3-X08"}],"explanation":["m끼리 1 + 2 + 3 = 6이에요.","cm끼리 20 + 35 + 4 = 59예요.","4 cm를 40 cm로 보면 안 돼요 — 6 m 59 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#6','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'error','auto','2 m 24 cm + 7 m 5 cm를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C5","difficulty":3,"kind":"error","stem":"2 m 24 cm + 7 m 5 cm를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 「cm끼리 24 + 50 = 74니까 9 m 74 cm야.」","correct":true,"mis_target":"M2-2-u3-X09"},{"t":"은솔 — 「m끼리 9, cm끼리 29니까 9 m 29 cm야.」","mis":"M2-2-u3-X16"},{"t":"예린 — 「224 cm + 705 cm = 929 cm = 9 m 29 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["7 m 5 cm의 cm는 5예요.","cm끼리 24 + 5 = 29예요.","도윤이는 5를 50처럼 더했어요 — 9 m 29 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#7','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 12 m 45 cm를 굴러간 뒤 6 m 32 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 12 m 45 cm를 굴러간 뒤 6 m 32 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 12 + 6 = 18.","cm는 cm끼리 더해요 — 45 + 32 = 77.","그래서 12 m 45 cm + 6 m 32 cm = 18 m 77 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"18 m 77 cm","correct":true},{"t":"6 m 13 cm","mis":"M2-2-u3-X10"},{"t":"19 m 77 cm","mis":"M2-2-u3-X08"},{"t":"18 m 87 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#8','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'essay','teacher','4 m 26 cm + 1 m 60 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"4 m 26 cm + 1 m 60 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.","answer_guide":{"answer":"예: 같은 단위끼리 맞추어 쓴다. cm끼리 26 + 60 = 86, m끼리 4 + 1 = 5를 더한다. 두 길이의 합은 5 m 86 cm이다.","scoring_points":["같은 단위끼리 맞추어 쓴다고 했는가","cm끼리·m끼리 더했는가","5 m 86 cm라고 바르게 구했는가"]},"explanation":["m는 m 아래, cm는 cm 아래에 맞추어 써요.","cm끼리 86, m끼리 5예요.","두 길이의 합은 5 m 86 cm예요."],"asset":{"type":"mcm_calc","a":[4,26],"b":[1,60],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#9','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'essay','teacher','2 m 30 cm + 1 m 40 cm를 3 m 7 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"2 m 30 cm + 1 m 40 cm를 3 m 7 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: cm끼리 더한 30 + 40 = 70을 7이라고 썼다. 바르게 계산하면 m끼리 3, cm끼리 70이므로 3 m 70 cm이다.","scoring_points":["70을 7로 쓴 잘못을 찾았는가","cm끼리 70, m끼리 3을 구했는가","3 m 70 cm라고 바르게 썼는가"]},"explanation":["cm끼리 30 + 40 = 70이에요.","70의 0을 떼면 7 cm가 되어 10배나 짧아져요.","바른 답은 3 m 70 cm예요."],"asset":{"type":"mcm_calc","a":[2,30],"b":[1,40],"op":"+","ask":"both","said":[3,7]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#10','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'mc','auto','달리기 길은 세 구간이에요. 첫째 15 m 40 cm, 둘째 12 m 35 cm, 셋째 21 m 10 cm예요. 달리기 길은 모두 얼마인가요?',ARRAY['M2-2-u3-X08','M2-2-u3-X16']::text[],false,'{"seq":10,"concept":"M2-2-u3-C5","difficulty":4,"kind":"mc","stem":"달리기 길은 세 구간이에요. 첫째 15 m 40 cm, 둘째 12 m 35 cm, 셋째 21 m 10 cm예요. 달리기 길은 모두 얼마인가요?","options":[{"t":"48 m 85 cm","correct":true},{"t":"47 m 85 cm","mis":"M2-2-u3-X08"},{"t":"48 m 75 cm","mis":"M2-2-u3-X08"},{"t":"27 m 75 cm","mis":"M2-2-u3-X16"}],"explanation":["m끼리 15 + 12 + 21 = 48이에요.","cm끼리 40 + 35 + 10 = 85예요.","그래서 모두 48 m 85 cm예요 — 두 구간만 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#1','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'mc','auto','6 m 80 cm − 4 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],true,'{"seq":1,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"6 m 80 cm − 4 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 80 − 50 = 30.","그래서 6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#2','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C6","difficulty":1,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 7 − 5 = 2.","cm는 cm끼리 빼요 — 74 − 32 = 42.","그래서 7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"calc","calc":"cm"}},"answer":["42"],"asset":{"type":"mcm_calc","a":[7,74],"b":[5,32],"op":"-","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#3','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'sa','auto','세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C6","difficulty":1,"kind":"sa","stem":"세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 4 − 1 = 3.","cm는 cm끼리 빼요 — 29 − 6 = 23.","그래서 4 m 29 cm − 1 m 6 cm = 3 m 23 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"calc","calc":"m"}},"answer":["3"],"asset":{"type":"mcm_calc","a":[4,29],"b":[1,6],"op":"-","ask":"m"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#4','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'ox','auto','길이의 차를 구한 뒤 뺀 길이를 다시 더하면 처음 길이가 나와요.',ARRAY['M2-2-u3-X10']::text[],true,'{"seq":4,"concept":"M2-2-u3-C6","difficulty":1,"kind":"ox","stem":"길이의 차를 구한 뒤 뺀 길이를 다시 더하면 처음 길이가 나와요.","answer":"O","reason_options":[{"t":"남은 길이와 뺀 길이를 모으면 처음 길이가 되니까","correct":true},{"t":"빼고 나서 더하면 늘 다른 길이가 되니까","mis":"M2-2-u3-X10"}],"mis":"M2-2-u3-X10","explanation":["2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요.","1 m 10 cm + 1 m 40 cm = 2 m 50 cm예요.","그래서 더해 보면 차가 맞는지 확인할 수 있어요."],"variant_rule":{"alt":[{"stem":"7 m 74 cm − 5 m 32 cm = 2 m 42 cm가 맞는지 보려면 2 m 42 cm + 5 m 32 cm를 계산해요.","answer":"O","reason_options":[{"t":"차에 뺀 길이를 더하면 처음 길이가 나와야 하니까","correct":true},{"t":"차를 확인할 때는 처음 길이를 한 번 더 빼야 하니까","mis":"M2-2-u3-X10"}],"explanation":["2 m 42 cm + 5 m 32 cm를 계산해요.","m끼리 7, cm끼리 74 — 7 m 74 cm예요.","처음 길이가 나왔으니 차가 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#5','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','2 m 50 cm인 색 테이프에서 1 m 40 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"2 m 50 cm인 색 테이프에서 1 m 40 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 2 − 1 = 1.","cm는 cm끼리 빼요 — 50 − 40 = 10.","그래서 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"1 m 10 cm","correct":true},{"t":"3 m 90 cm","mis":"M2-2-u3-X10"},{"t":"1 m 1 cm","mis":"M2-2-u3-X11"}],"asset":{"type":"mbar","parts":[[2,50],[1,40]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#6','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','3 m 75 cm인 색 테이프에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"3 m 75 cm인 색 테이프에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 3 − 1 = 2.","cm는 cm끼리 빼요 — 75 − 52 = 23.","그래서 3 m 75 cm − 1 m 52 cm = 2 m 23 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"2 m 23 cm","correct":true},{"t":"3 m 23 cm","mis":"M2-2-u3-X08"},{"t":"2 m 33 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[3,75],[1,52]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#7','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 9 − 1 = 8.","cm는 cm끼리 빼요 — 48 − 3 = 45.","그래서 9 m 48 cm − 1 m 3 cm = 8 m 45 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"8 m 45 cm","correct":true},{"t":"10 m 51 cm","mis":"M2-2-u3-X10"},{"t":"8 m 18 cm","mis":"M2-2-u3-X09"},{"t":"9 m 45 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#8','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'error','auto','어떤 친구가 5 m 64 cm − 3 m 22 cm를 이렇게 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":8,"concept":"M2-2-u3-C6","difficulty":2,"kind":"error","stem":"어떤 친구가 5 m 64 cm − 3 m 22 cm를 이렇게 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"빼야 하는데 더했어요","correct":true,"mis_target":"M2-2-u3-X10"},{"t":"cm 자리만 계산했어요","mis":"M2-2-u3-X08"},{"t":"m 자리를 잘못 읽었어요","mis":"M2-2-u3-X08"}],"explanation":["5 m 64 cm − 3 m 22 cm는 차를 구하는 식이에요.","8 m 86 cm는 두 길이를 더한 값이에요.","바르게 빼면 m끼리 2, cm끼리 42 — 2 m 42 cm예요."],"asset":{"type":"mcm_calc","a":[5,64],"b":[3,22],"op":"-","ask":"both","said":[8,86]},"variant_rule":{"alt":[{"stem":"어떤 친구가 6 m 45 cm − 2 m 31 cm를 이렇게 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"빼야 하는데 더했어요","correct":true,"mis_target":"M2-2-u3-X10"},{"t":"cm 자리만 계산했어요","mis":"M2-2-u3-X08"},{"t":"m 자리를 잘못 읽었어요","mis":"M2-2-u3-X08"}],"explanation":["6 m 45 cm − 2 m 31 cm는 차를 구하는 식이에요.","8 m 76 cm는 두 길이를 더한 값이에요.","바르게 빼면 m끼리 4, cm끼리 14 — 4 m 14 cm예요."],"asset":{"type":"mcm_calc","a":[6,45],"b":[2,31],"op":"-","ask":"both","said":[8,76]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#9','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','8 m 47 cm − 2 m 5 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"8 m 47 cm − 2 m 5 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 2 = 6.","cm는 cm끼리 빼요 — 47 − 5 = 42.","그래서 8 m 47 cm − 2 m 5 cm = 6 m 42 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"6 m 42 cm","correct":true},{"t":"10 m 52 cm","mis":"M2-2-u3-X10"},{"t":"7 m 42 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#10','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',3,'mc','auto','나무 2 m 50 cm에서 1 m 40 cm를 사용했어요. 남은 나무로 1 m 20 cm짜리 다리를 만들 수 있나요?',ARRAY['M2-2-u3-X10','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"나무 2 m 50 cm에서 1 m 40 cm를 사용했어요. 남은 나무로 1 m 20 cm짜리 다리를 만들 수 있나요?","options":[{"t":"아니요 — 남은 나무가 1 m 10 cm라 10 cm 모자라요","correct":true},{"t":"네 — 남은 나무가 3 m 90 cm예요","mis":"M2-2-u3-X10"},{"t":"네 — 1 m 40 cm가 1 m 20 cm보다 기니까","mis":"M2-2-u3-X16"}],"explanation":["남은 나무는 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요.","1 m 10 cm는 1 m 20 cm보다 10 cm 짧아요.","그래서 다리를 만들 수 없어요."],"variant_rule":{"alt":[{"stem":"끈 3 m 60 cm에서 2 m 10 cm를 사용했어요. 남은 끈으로 1 m 30 cm짜리 줄을 만들 수 있나요?","options":[{"t":"네 — 남은 끈이 1 m 50 cm라 20 cm 남아요","correct":true},{"t":"아니요 — 남은 끈이 5 m 70 cm예요","mis":"M2-2-u3-X10"},{"t":"아니요 — 2 m 10 cm가 더 기니까","mis":"M2-2-u3-X16"}],"explanation":["남은 끈은 3 m 60 cm − 2 m 10 cm = 1 m 50 cm예요.","1 m 50 cm는 1 m 30 cm보다 20 cm 길어요.","그래서 줄을 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#1','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',2,'mc','auto','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":1,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 88 − 26 = 62.","그래서 6 m 88 cm − 4 m 26 cm = 2 m 62 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"two"}},"options":[{"t":"2 m 62 cm","correct":true},{"t":"3 m 62 cm","mis":"M2-2-u3-X08"},{"t":"2 m 72 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#2','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":2,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 3 = 5.","cm는 cm끼리 빼요 — 65 − 40 = 25.","그래서 8 m 65 cm − 3 m 40 cm = 5 m 25 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"calc"}},"options":[{"t":"5 m 25 cm","correct":true},{"t":"6 m 25 cm","mis":"M2-2-u3-X08"},{"t":"5 m 35 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[8,65],"b":[3,40],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#3','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','9 m 76 cm − □ m 34 cm = 4 m 42 cm에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":3,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"9 m 76 cm − □ m 34 cm = 4 m 42 cm에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"13","mis":"M2-2-u3-X10"},{"t":"4","mis":"M2-2-u3-X08"}],"explanation":["cm끼리 76 − 34 = 42로 맞아요.","m끼리 9 − □ = 4예요.","9 − 5 = 4이니 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#4','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 9 m 87 cm와 1 m 22 cm예요. 두 막대의 길이의 차는 8 m 45 cm보다 긴가요?',ARRAY['M2-2-u3-X08','M2-2-u3-X10']::text[],false,'{"seq":4,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 9 m 87 cm와 1 m 22 cm예요. 두 막대의 길이의 차는 8 m 45 cm보다 긴가요?","options":[{"t":"네 — 차가 8 m 65 cm라 더 길어요","correct":true},{"t":"아니요 — 차가 8 m 45 cm와 같아요","mis":"M2-2-u3-X08"},{"t":"아니요 — 차가 11 m 9 cm예요","mis":"M2-2-u3-X10"}],"explanation":["m끼리 9 − 1 = 8, cm끼리 87 − 22 = 65예요.","차는 8 m 65 cm예요.","8 m 65 cm는 8 m 45 cm보다 20 cm 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#5','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','막대 가는 3 m 85 cm, 나는 2 m 40 cm, 다는 5 m 96 cm예요. 가장 긴 막대와 가장 짧은 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"막대 가는 3 m 85 cm, 나는 2 m 40 cm, 다는 5 m 96 cm예요. 가장 긴 막대와 가장 짧은 막대의 길이의 차는 얼마인가요?","options":[{"t":"3 m 56 cm","correct":true},{"t":"2 m 11 cm","mis":"M2-2-u3-X16"},{"t":"8 m 36 cm","mis":"M2-2-u3-X10"}],"explanation":["가장 긴 막대는 다(5 m 96 cm), 가장 짧은 막대는 나(2 m 40 cm)예요.","m끼리 5 − 2 = 3, cm끼리 96 − 40 = 56이에요.","그래서 차는 3 m 56 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#6','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'error','auto','4 m 29 cm − 1 m 6 cm를 친구들이 계산했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":3,"kind":"error","stem":"4 m 29 cm − 1 m 6 cm를 친구들이 계산했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「29에서 60은 뺄 수 없으니 계산할 수 없어.」","correct":true,"mis_target":"M2-2-u3-X09"},{"t":"아린 — 「m끼리 3, cm끼리 23이니 3 m 23 cm야.」","mis":"M2-2-u3-X16"},{"t":"지안 — 「3 m 23 cm에 1 m 6 cm를 더하면 4 m 29 cm라 맞아.」","mis":"M2-2-u3-X16"}],"explanation":["1 m 6 cm의 cm는 6이에요.","cm끼리 29 − 6 = 23이에요.","태민이는 6을 60으로 보았어요 — 답은 3 m 23 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#7','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','색 테이프 7 m 58 cm 가운데 2 m 15 cm는 상자 포장에, 3 m 21 cm는 리본에 썼어요. 남은 색 테이프는 얼마인가요?',ARRAY['M2-2-u3-X08','M2-2-u3-X10']::text[],false,'{"seq":7,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"색 테이프 7 m 58 cm 가운데 2 m 15 cm는 상자 포장에, 3 m 21 cm는 리본에 썼어요. 남은 색 테이프는 얼마인가요?","options":[{"t":"2 m 22 cm","correct":true},{"t":"5 m 43 cm","mis":"M2-2-u3-X08"},{"t":"12 m 94 cm","mis":"M2-2-u3-X10"}],"explanation":["상자 포장에 쓰고 남은 것은 7 m 58 cm − 2 m 15 cm = 5 m 43 cm예요.","리본에 쓰고 남은 것은 5 m 43 cm − 3 m 21 cm = 2 m 22 cm예요.","두 번 빼야 해요 — 한 번만 빼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#8','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'essay','teacher','7 m 74 cm − 5 m 32 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"7 m 74 cm − 5 m 32 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: m끼리 7 − 5 = 2, cm끼리 74 − 32 = 42이므로 2 m 42 cm이다. 2 m 42 cm + 5 m 32 cm = 7 m 74 cm가 되어 처음 길이가 나오므로 맞다.","scoring_points":["2 m 42 cm를 바르게 구했는가","차에 뺀 길이를 더해 확인했는가","처음 길이 7 m 74 cm가 나오는지 말했는가"]},"explanation":["m끼리, cm끼리 빼면 2 m 42 cm예요.","2 m 42 cm + 5 m 32 cm = 7 m 74 cm예요.","처음 길이가 나오면 차가 맞아요."],"asset":{"type":"mcm_calc","a":[7,74],"b":[5,32],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#9','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'essay','teacher','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐더니 한 도막이 4 m 26 cm였어요. 다른 도막의 길이를 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐더니 한 도막이 4 m 26 cm였어요. 다른 도막의 길이를 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 다른 도막은 전체에서 한 도막을 뺀 길이이다. 6 m 88 cm − 4 m 26 cm에서 m끼리 2, cm끼리 62이므로 2 m 62 cm이다.","scoring_points":["뺄셈으로 구해야 함을 썼는가","m끼리·cm끼리 뺐는가","2 m 62 cm라고 바르게 구했는가"]},"explanation":["두 도막을 이으면 처음 막대가 돼요.","그래서 다른 도막은 6 m 88 cm − 4 m 26 cm예요.","2 m 62 cm예요."],"asset":{"type":"mbar","parts":[[6,88],[4,26]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#10','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'mc','auto','빨간 끈은 4 m 35 cm이고, 파란 끈은 빨간 끈보다 1 m 20 cm 짧아요. 두 끈의 길이의 합은 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":10,"concept":"M2-2-u3-C6","difficulty":4,"kind":"mc","stem":"빨간 끈은 4 m 35 cm이고, 파란 끈은 빨간 끈보다 1 m 20 cm 짧아요. 두 끈의 길이의 합은 얼마인가요?","options":[{"t":"7 m 50 cm","correct":true},{"t":"3 m 15 cm","mis":"M2-2-u3-X16"},{"t":"9 m 90 cm","mis":"M2-2-u3-X10"}],"explanation":["파란 끈은 4 m 35 cm − 1 m 20 cm = 3 m 15 cm예요.","두 끈의 합은 4 m 35 cm + 3 m 15 cm예요.","m끼리 7, cm끼리 50 — 7 m 50 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#1','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','교실 문의 짧은 쪽을 자로 재지 않고 1 m쯤으로 짐작했어요. 어림한 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X17']::text[],true,'{"seq":1,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"교실 문의 짧은 쪽을 자로 재지 않고 1 m쯤으로 짐작했어요. 어림한 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 1 m","correct":true},{"t":"1 m","mis":"M2-2-u3-X12"},{"t":"약 1 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 것을 어림이라고 해요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 1 m라고 말해요."],"variant_rule":{"alt":[{"stem":"책꽂이의 긴 쪽을 자로 재지 않고 2 m쯤으로 짐작했어요. 어림한 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 2 m","correct":true},{"t":"2 m","mis":"M2-2-u3-X12"},{"t":"약 2 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 것을 어림이라고 해요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 2 m라고 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#2','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','양팔을 벌린 길이는 약 몇 m인가요?',ARRAY['M2-2-u3-X17']::text[],true,'{"seq":2,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"양팔을 벌린 길이는 약 몇 m인가요?","options":[{"t":"약 1 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X17"},{"t":"약 1 cm","mis":"M2-2-u3-X17"}],"explanation":["양팔을 쭉 벌린 길이는 1 m쯤이에요.","그래서 1 m를 어림할 때 양팔을 벌려 봐요.","약 1 cm는 손톱 너비, 약 10 m는 교실보다 길어요."],"variant_rule":{"alt":[{"stem":"교실 문의 높이는 약 몇 m인가요?","options":[{"t":"약 2 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X17"},{"t":"약 2 cm","mis":"M2-2-u3-X17"}],"explanation":["교실 문은 어른 키보다 조금 높아요.","1 m의 두 배쯤이에요.","그래서 약 2 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#3','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'sa','auto','한 칸이 약 1 m인 간격이 3개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C7","difficulty":1,"kind":"sa","stem":"한 칸이 약 1 m인 간격이 3개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.","explanation":["약 1 m가 3번 있어요.","1 + 1 + 1 = 3이에요.","그래서 모두 약 3 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"answer":["3"],"asset":{"type":"est_row","seg":1,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#4','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'ox','auto','어림한 길이는 자로 잰 길이와 반드시 같아야 해요.',ARRAY['M2-2-u3-X12']::text[],true,'{"seq":4,"concept":"M2-2-u3-C7","difficulty":1,"kind":"ox","stem":"어림한 길이는 자로 잰 길이와 반드시 같아야 해요.","answer":"X","reason_options":[{"t":"어림은 짐작한 것이라 잰 길이와 조금 다를 수 있으니까","correct":true},{"t":"어림한 길이가 잰 길이와 다르면 틀린 것이니까","mis":"M2-2-u3-X12"}],"mis":"M2-2-u3-X12","explanation":["어림은 자로 재지 않고 짐작하는 거예요.","그래서 잰 길이와 조금 다를 수 있어요.","어림한 뒤 자로 재어 확인하면 다음엔 더 가깝게 어림해요."],"variant_rule":{"alt":[{"stem":"어림한 길이 앞에는 「약」을 붙여요.","answer":"O","reason_options":[{"t":"자로 재지 않고 짐작한 길이라서","correct":true},{"t":"「약」은 잰 길이 앞에만 붙이니까","mis":"M2-2-u3-X12"}],"explanation":["어림은 짐작한 길이예요.","짐작한 길이에는 「약」을 붙여요.","그래서 「약 1 m」처럼 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#5','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','신발장의 길이를 지아는 양팔을 벌린 길이로, 세미는 걸음으로, 슬기는 뼘으로 재었어요. 잰 횟수가 가장 많은 사람은 누구인가요?',ARRAY['M2-2-u3-X13']::text[],true,'{"seq":5,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"신발장의 길이를 지아는 양팔을 벌린 길이로, 세미는 걸음으로, 슬기는 뼘으로 재었어요. 잰 횟수가 가장 많은 사람은 누구인가요?","options":[{"t":"슬기","correct":true},{"t":"지아","mis":"M2-2-u3-X13"},{"t":"모두 같다","mis":"M2-2-u3-X13"}],"explanation":["뼘이 양팔이나 걸음보다 짧아요.","짧은 단위로 재면 더 여러 번 재야 해요.","그래서 뼘으로 잰 슬기의 횟수가 가장 많아요."],"variant_rule":{"alt":[{"stem":"복도의 길이를 도윤이는 걸음으로, 은솔이는 뼘으로 재었어요. 잰 횟수가 더 적은 사람은 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"은솔","mis":"M2-2-u3-X13"},{"t":"둘이 같다","mis":"M2-2-u3-X13"}],"explanation":["걸음이 뼘보다 길어요.","긴 단위로 재면 더 적게 재요.","그래서 걸음으로 잰 도윤이의 횟수가 더 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#6','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":6,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 4 m는 1 m가 4번이니 3걸음씩 4번 — 3 + 3 + 3 + 3 = 12예요.","그래서 약 12걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 12걸음","correct":true},{"t":"약 7걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#7','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'match','auto','어림한 길이에 알맞은 잰 길이를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":2,"kind":"match","stem":"어림한 길이에 알맞은 잰 길이를 이으세요.","pairs":[{"l":"약 1 m","r":"96 cm"},{"l":"약 2 m","r":"1 m 90 cm"},{"l":"약 3 m","r":"3 m 10 cm"}],"mis":"M2-2-u3-X12","explanation":["96 cm는 1 m에 가까워요.","1 m 90 cm는 2 m에 가까워요.","3 m 10 cm는 3 m에 가까워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 어림한 길이에 알맞은 잰 길이를 이으세요.","pairs":[{"l":"약 1 m","r":"1 m 2 cm"},{"l":"약 2 m","r":"2 m 10 cm"},{"l":"약 3 m","r":"2 m 80 cm"}],"explanation":["1 m 2 cm는 1 m에 가까워요.","2 m 10 cm는 2 m에 가까워요.","2 m 80 cm는 3 m에 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#8','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','칠판의 긴 쪽은 얼마쯤일까요? 알맞게 어림한 것을 고르세요.',ARRAY['M2-2-u3-X17']::text[],true,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"칠판의 긴 쪽은 얼마쯤일까요? 알맞게 어림한 것을 고르세요.","options":[{"t":"약 3 m","correct":true},{"t":"약 3 cm","mis":"M2-2-u3-X17"},{"t":"약 30 m","mis":"M2-2-u3-X17"}],"explanation":["칠판의 긴 쪽은 양팔을 세 번쯤 벌린 길이예요.","1 m가 세 번쯤이니 약 3 m예요.","약 3 cm는 너무 짧고, 약 30 m는 너무 길어요."],"variant_rule":{"alt":[{"stem":"교실 책상의 긴 쪽은 얼마쯤일까요? 알맞게 어림한 것을 고르세요.","options":[{"t":"약 60 cm","correct":true},{"t":"약 6 m","mis":"M2-2-u3-X17"},{"t":"약 6 cm","mis":"M2-2-u3-X17"}],"explanation":["책상의 긴 쪽은 양팔을 벌린 길이보다 짧아요.","1 m보다 짧으니 cm로 어림해요.","약 60 cm가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#9','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','한 칸이 약 1 m인 간격이 4개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":9,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"한 칸이 약 1 m인 간격이 4개 있어요. 모두 약 몇 m인가요?","explanation":["약 1 m가 4번 있어요.","1 + 1 + 1 + 1 = 4예요.","그래서 모두 약 4 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 4 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X14"},{"t":"약 3 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#10','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',3,'error','auto','1 m를 걸음으로 재어 보았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X13','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C7","difficulty":3,"kind":"error","stem":"1 m를 걸음으로 재어 보았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「나는 2걸음이니까 세미도 꼭 2걸음일 거야.」","correct":true,"mis_target":"M2-2-u3-X13"},{"t":"세미 — 「나는 3걸음이야. 사람마다 다를 수 있어.」","mis":"M2-2-u3-X16"},{"t":"슬기 — 「잴 때마다 걸음의 크기를 같게 해야 해.」","mis":"M2-2-u3-X16"}],"explanation":["사람마다 걸음의 크기가 달라요.","그래서 같은 1 m도 잰 걸음 수가 다를 수 있어요.","지아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"1 m를 뼘으로 재어 보았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「누가 재어도 1 m는 꼭 7뼘이야.」","correct":true,"mis_target":"M2-2-u3-X13"},{"t":"곰이 — 「손이 큰 사람은 뼘 수가 적을 거야.」","mis":"M2-2-u3-X16"},{"t":"펭이 — 「잴 때마다 뼘을 똑같이 벌려야 해.」","mis":"M2-2-u3-X16"}],"explanation":["사람마다 뼘의 크기가 달라요.","손이 크면 뼘 수가 적어요.","하람이의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#1','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":1,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 5 m는 1 m가 5번이니 2걸음씩 5번 — 2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 약 10걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 10걸음","correct":true},{"t":"약 7걸음","mis":"M2-2-u3-X14"},{"t":"약 5걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#2','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',2,'mc','auto','1 m가 뼘으로 약 7번이에요. 약 2 m는 뼘으로 약 몇 번일까요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":2,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 뼘으로 약 7번이에요. 약 2 m는 뼘으로 약 몇 번일까요?","options":[{"t":"약 14번","correct":true},{"t":"약 9번","mis":"M2-2-u3-X14"},{"t":"약 7번","mis":"M2-2-u3-X14"}],"explanation":["약 2 m는 1 m가 두 번이에요.","7번씩 두 번이니 7 + 7 = 14예요.","그래서 약 14번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#3','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','끈을 약 2 m로 어림하고 자로 재어 보니 1 m 90 cm였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X18']::text[],false,'{"seq":3,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"끈을 약 2 m로 어림하고 자로 재어 보니 1 m 90 cm였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"어림한 길이와 잰 길이가 10 cm 차이 나요","correct":true},{"t":"어림한 길이가 잰 길이와 다르니 잘못 어림했어요","mis":"M2-2-u3-X12"},{"t":"1 m 90 cm는 2 m보다 길어요","mis":"M2-2-u3-X18"}],"explanation":["2 m는 200 cm, 1 m 90 cm는 190 cm예요.","200 − 190 = 10이니 10 cm 차이예요.","어림은 짐작이라 조금 달라도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#4','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','세 사람이 칠판의 긴 쪽을 어림했어요. 가는 약 2 m, 나는 약 3 m, 다는 약 4 m라고 했어요. 자로 재어 보니 2 m 80 cm였어요. 가장 가깝게 어림한 사람은 누구인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X14']::text[],false,'{"seq":4,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 칠판의 긴 쪽을 어림했어요. 가는 약 2 m, 나는 약 3 m, 다는 약 4 m라고 했어요. 자로 재어 보니 2 m 80 cm였어요. 가장 가깝게 어림한 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-2-u3-X18"},{"t":"다","mis":"M2-2-u3-X14"}],"explanation":["2 m 80 cm는 280 cm예요.","약 3 m(300 cm)는 20 cm, 약 2 m(200 cm)는 80 cm 차이예요.","그래서 나가 가장 가깝게 어림했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#5','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'ox','auto','키가 다른 두 친구가 같은 길이를 걸음으로 재면 걸음 수가 다를 수 있어요.',ARRAY['M2-2-u3-X13']::text[],false,'{"seq":5,"concept":"M2-2-u3-C7","difficulty":3,"kind":"ox","stem":"키가 다른 두 친구가 같은 길이를 걸음으로 재면 걸음 수가 다를 수 있어요.","answer":"O","reason_options":[{"t":"걸음의 크기가 사람마다 다르니까","correct":true},{"t":"같은 길이면 누가 재도 걸음 수가 같으니까","mis":"M2-2-u3-X13"}],"mis":"M2-2-u3-X13","explanation":["걸음의 크기는 사람마다 달라요.","큰 걸음은 적게, 작은 걸음은 많이 걸어요.","그래서 걸음 수가 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#6','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','알맞게 어림한 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":6,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"알맞게 어림한 것은 어느 것인가요?","options":[{"t":"교실 문의 높이 — 약 2 m","correct":true},{"t":"필통의 길이 — 약 2 m","mis":"M2-2-u3-X17"},{"t":"운동장의 긴 쪽 — 약 2 m","mis":"M2-2-u3-X17"},{"t":"수학책의 긴 쪽 — 약 2 m","mis":"M2-2-u3-X17"}],"explanation":["약 2 m는 양팔을 두 번 벌린 길이쯤이에요.","필통·수학책은 훨씬 짧고, 운동장은 훨씬 길어요.","교실 문의 높이가 약 2 m에 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#7','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'sa','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":3,"kind":"sa","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요? 숫자로 쓰세요.","explanation":["1 m가 약 3걸음이에요.","약 6 m는 1 m가 6번이니 3걸음씩 6번 — 3 + 3 + 3 + 3 + 3 + 3 = 18이에요.","그래서 약 18걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#8','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'essay','teacher','1 m를 기준 삼아 교실 칠판의 긴 쪽 길이를 어림하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":4,"kind":"essay","stem":"1 m를 기준 삼아 교실 칠판의 긴 쪽 길이를 어림하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 양팔을 벌린 길이가 약 1 m이다. 칠판 끝에서부터 양팔을 벌려 몇 번쯤 되는지 본다. 세 번쯤이면 약 3 m로 어림하고, 줄자로 재어 확인한다.","scoring_points":["1 m를 몸의 부분 등으로 정했는가","1 m가 몇 번쯤인지 보고 어림한다고 썼는가","「약」을 붙이거나 자로 재어 확인한다고 썼는가"]},"explanation":["1 m가 얼마쯤인지 몸으로 먼저 알아 둬요.","1 m가 몇 번쯤인지 보면 길이를 어림할 수 있어요.","어림한 뒤 자로 재어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#9','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'essay','teacher','지아는 1 m가 두 걸음, 세미는 세 걸음이에요. 두 사람이 같은 복도를 걸음으로 재면 누구의 걸음 수가 더 많을지 쓰고, 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C7","difficulty":4,"kind":"essay","stem":"지아는 1 m가 두 걸음, 세미는 세 걸음이에요. 두 사람이 같은 복도를 걸음으로 재면 누구의 걸음 수가 더 많을지 쓰고, 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 세미의 걸음 수가 더 많다. 세미는 1 m를 세 걸음에 가므로 걸음이 지아보다 작다. 작은 단위로 재면 더 여러 번 재야 한다.","scoring_points":["세미라고 답했는가","세미의 걸음이 더 작다고 썼는가","작은 단위로 재면 횟수가 많아진다고 썼는가"]},"explanation":["1 m를 지아는 2걸음, 세미는 3걸음에 가요.","세미의 한 걸음이 더 작아요.","작은 걸음으로 재면 걸음 수가 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#10','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'mc','auto','바다악어의 몸길이는 약 3 m예요. 양팔을 벌린 길이가 약 1 m인 친구 몇 명이 팔을 벌리고 나란히 서면 바다악어의 몸길이와 비슷할까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X01']::text[],false,'{"seq":10,"concept":"M2-2-u3-C7","difficulty":4,"kind":"mc","stem":"바다악어의 몸길이는 약 3 m예요. 양팔을 벌린 길이가 약 1 m인 친구 몇 명이 팔을 벌리고 나란히 서면 바다악어의 몸길이와 비슷할까요?","options":[{"t":"약 3명","correct":true},{"t":"약 1명","mis":"M2-2-u3-X14"},{"t":"약 30명","mis":"M2-2-u3-X01"}],"explanation":["친구 한 명이 약 1 m예요.","약 3 m는 1 m가 세 번이에요.","그래서 약 3명이 나란히 서면 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#1','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','축구 골대의 긴 쪽은 약 5 m예요. 약 5 m의 두 배쯤은 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":1,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"축구 골대의 긴 쪽은 약 5 m예요. 약 5 m의 두 배쯤은 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 5 m","mis":"M2-2-u3-X14"}],"explanation":["두 배쯤은 같은 길이가 두 번이에요.","5 + 5 = 10이에요.","그래서 약 10 m예요."],"variant_rule":{"alt":[{"stem":"그네의 길이는 약 4 m예요. 약 4 m의 두 배쯤은 약 몇 m인가요?","options":[{"t":"약 8 m","correct":true},{"t":"약 6 m","mis":"M2-2-u3-X14"},{"t":"약 4 m","mis":"M2-2-u3-X14"}],"explanation":["두 배쯤은 같은 길이가 두 번이에요.","4 + 4 = 8이에요.","그래서 약 8 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#2','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'sa','auto','한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C8","difficulty":1,"kind":"sa","stem":"한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.","explanation":["약 2 m가 5번 있어요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 모두 약 10 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"answer":["10"],"asset":{"type":"est_row","seg":2,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#3','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','운동장의 짧은 쪽을 끝~골대 약 10 m, 골대 약 5 m, 골대~끝 약 10 m로 나누어 어림했어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":3,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"운동장의 짧은 쪽을 끝~골대 약 10 m, 골대 약 5 m, 골대~끝 약 10 m로 나누어 어림했어요. 모두 약 몇 m인가요?","options":[{"t":"약 25 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X14"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 길이를 모두 더해요.","10 + 5 + 10 = 25예요.","그래서 약 25 m예요."],"variant_rule":{"alt":[{"stem":"복도를 계단~교실 약 8 m, 교실 앞 약 6 m, 교실~도서관 약 8 m로 나누어 어림했어요. 모두 약 몇 m인가요?","options":[{"t":"약 22 m","correct":true},{"t":"약 16 m","mis":"M2-2-u3-X14"},{"t":"약 14 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 길이를 모두 더해요.","8 + 6 + 8 = 22예요.","그래서 약 22 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#4','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'ox','auto','긴 거리는 몇 부분으로 나누어 어림한 뒤 모두 더할 수 있어요.',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":4,"concept":"M2-2-u3-C8","difficulty":1,"kind":"ox","stem":"긴 거리는 몇 부분으로 나누어 어림한 뒤 모두 더할 수 있어요.","answer":"O","reason_options":[{"t":"부분마다 어림한 길이를 더하면 전체 길이가 되니까","correct":true},{"t":"긴 거리는 한 번에 눈으로 보고 정해야만 하니까","mis":"M2-2-u3-X14"}],"mis":"M2-2-u3-X14","explanation":["긴 거리는 한 번에 짐작하기 어려워요.","몇 부분으로 나누면 부분마다 어림하기 쉬워요.","부분의 길이를 모두 더하면 전체 길이예요."],"variant_rule":{"alt":[{"stem":"이미 어림한 5 m를 기준 삼으면 10 m도 어림할 수 있어요.","answer":"O","reason_options":[{"t":"5 m가 두 번쯤이면 약 10 m니까","correct":true},{"t":"5 m와 10 m는 서로 관계가 없으니까","mis":"M2-2-u3-X14"}],"explanation":["5 m를 알고 있으면 기준으로 쓸 수 있어요.","5 m가 두 번쯤이면 약 10 m예요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#5','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":5,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 5명이면 사이 간격은 4개예요.","약 1 m씩 4번이니 약 4 m예요.","사람 수만큼 5번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 4 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X15"},{"t":"약 6 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":5,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#6','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":6,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 3번 있어요.","5 + 5 + 5 = 15예요.","그래서 모두 약 15 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 15 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X14"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#7','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'match','auto','어림한 거리에 알맞은 곳을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":2,"kind":"match","stem":"어림한 거리에 알맞은 곳을 이으세요.","pairs":[{"l":"약 1 m","r":"교실 문의 짧은 쪽"},{"l":"약 5 m","r":"축구 골대의 긴 쪽"},{"l":"약 25 m","r":"운동장의 짧은 쪽"}],"mis":"M2-2-u3-X17","explanation":["교실 문의 짧은 쪽은 양팔 벌린 길이쯤 — 약 1 m예요.","축구 골대의 긴 쪽은 약 5 m예요.","운동장의 짧은 쪽은 약 25 m예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 어림한 거리에 알맞은 곳을 이으세요.","pairs":[{"l":"약 2 m","r":"교실 문의 높이"},{"l":"약 10 m","r":"교실 두 칸의 길이"},{"l":"약 50 m","r":"운동장의 긴 쪽"}],"explanation":["교실 문의 높이는 약 2 m예요.","교실 한 칸이 약 5 m라 두 칸은 약 10 m예요.","운동장의 긴 쪽은 약 50 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#8','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','울타리 한 칸은 약 2 m예요. 나무에서 그네까지 울타리가 세 칸이에요. 나무에서 그네까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":8,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"울타리 한 칸은 약 2 m예요. 나무에서 그네까지 울타리가 세 칸이에요. 나무에서 그네까지는 약 몇 m인가요?","options":[{"t":"약 6 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X14"},{"t":"약 3 m","mis":"M2-2-u3-X14"}],"explanation":["울타리 한 칸이 약 2 m예요.","세 칸이니 2 + 2 + 2 = 6이에요.","그래서 약 6 m예요."],"variant_rule":{"alt":[{"stem":"화단 한 칸은 약 3 m예요. 정문에서 놀이터까지 화단이 네 칸이에요. 정문에서 놀이터까지는 약 몇 m인가요?","options":[{"t":"약 12 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 4 m","mis":"M2-2-u3-X14"}],"explanation":["화단 한 칸이 약 3 m예요.","네 칸이니 3 + 3 + 3 + 3 = 12예요.","그래서 약 12 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#9','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":9,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 4명이면 사이 간격은 3개예요.","약 2 m씩 3번이니 약 6 m예요.","사람 수만큼 4번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 6 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":4,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#10','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',3,'mc','auto','운동장의 짧은 쪽을 나누어 어림해 약 25 m로 정했고, 자로 재어 보니 24 m였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12']::text[],true,'{"seq":10,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"운동장의 짧은 쪽을 나누어 어림해 약 25 m로 정했고, 자로 재어 보니 24 m였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누어 어림해서 잰 길이에 가깝게 어림했어요","correct":true},{"t":"어림한 값과 잰 값이 달라서 잘못 어림했어요","mis":"M2-2-u3-X12"},{"t":"어림한 값에 「약」을 붙여서 틀렸어요","mis":"M2-2-u3-X12"}],"explanation":["약 25 m와 24 m는 1 m 차이예요.","긴 거리에서 1 m 차이면 아주 가깝게 어림한 거예요.","나누어 어림하면 더 가깝게 어림할 수 있어요."],"variant_rule":{"alt":[{"stem":"복도를 약 2 m 간격의 기둥을 세어 약 20 m로 어림했고, 자로 재어 보니 21 m였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"간격을 세어 잰 길이에 가깝게 어림했어요","correct":true},{"t":"어림한 값과 잰 값이 달라서 잘못 어림했어요","mis":"M2-2-u3-X12"},{"t":"어림한 값에 「약」을 붙여서 틀렸어요","mis":"M2-2-u3-X12"}],"explanation":["약 20 m와 21 m는 1 m 차이예요.","긴 거리에서 1 m 차이면 아주 가깝게 어림한 거예요.","같은 간격을 세면 더 가깝게 어림할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#1','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',2,'mc','auto','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":1,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 8명이면 사이 간격은 7개예요.","약 1 m씩 7번이니 약 7 m예요.","사람 수만큼 8번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 7 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#2','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',2,'mc','auto','한 칸이 약 3 m인 간격이 4개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":2,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 3 m인 간격이 4개 있어요. 모두 약 몇 m인가요?","explanation":["약 3 m가 4번 있어요.","3 + 3 + 3 + 3 = 12예요.","그래서 모두 약 12 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 12 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":3,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#3','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','복도에 화분 6개가 약 2 m 간격으로 한 줄로 놓여 있어요. 첫 화분부터 마지막 화분까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":3,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"복도에 화분 6개가 약 2 m 간격으로 한 줄로 놓여 있어요. 첫 화분부터 마지막 화분까지는 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X15"},{"t":"약 8 m","mis":"M2-2-u3-X14"}],"explanation":["화분이 6개면 사이 간격은 5개예요.","약 2 m씩 5번이니 약 10 m예요.","화분 수만큼 6번 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#4','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','정문~현관 약 20 m, 현관~교실 약 15 m, 교실~과학실 약 10 m예요. 정문에서 교실을 지나 과학실까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":4,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"정문~현관 약 20 m, 현관~교실 약 15 m, 교실~과학실 약 10 m예요. 정문에서 교실을 지나 과학실까지는 약 몇 m인가요?","options":[{"t":"약 45 m","correct":true},{"t":"약 35 m","mis":"M2-2-u3-X14"},{"t":"약 30 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 세 부분을 모두 더해요.","20 + 15 + 10 = 45예요.","그래서 약 45 m예요 — 두 부분만 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#5','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','축구 골대의 긴 쪽은 약 5 m예요. 운동장의 긴 쪽에 골대를 8개 나란히 이어 놓을 수 있다면 운동장의 긴 쪽은 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],false,'{"seq":5,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"축구 골대의 긴 쪽은 약 5 m예요. 운동장의 긴 쪽에 골대를 8개 나란히 이어 놓을 수 있다면 운동장의 긴 쪽은 약 몇 m인가요?","options":[{"t":"약 40 m","correct":true},{"t":"약 13 m","mis":"M2-2-u3-X14"},{"t":"약 35 m","mis":"M2-2-u3-X15"}],"explanation":["약 5 m가 8번이에요.","5씩 8번 더하면 40이에요.","그래서 약 40 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#6','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'error','auto','학생 6명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C8","difficulty":3,"kind":"error","stem":"학생 6명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「6명이니까 약 6 m야.」","correct":true,"mis_target":"M2-2-u3-X15"},{"t":"펭이 — 「사이 간격이 5개니까 약 5 m야.」","mis":"M2-2-u3-X16"},{"t":"다예 — 「약 1 m씩 다섯 번이니 약 5 m야.」","mis":"M2-2-u3-X16"}],"explanation":["6명 사이의 간격은 5개예요.","약 1 m씩 5번이니 약 5 m예요.","곰이는 사람 수와 간격 수를 같다고 보았어요."],"asset":{"type":"est_row","seg":1,"n":6,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#7','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','같은 간격이 몇 개인지 세어 긴 거리를 어림하는 방법은 어느 것인가요?',ARRAY['M2-2-u3-X16']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"같은 간격이 몇 개인지 세어 긴 거리를 어림하는 방법은 어느 것인가요?","options":[{"t":"약 2 m 간격의 거리 표시가 몇 개인지 세어요","correct":true},{"t":"1 m를 기준 삼아 몇 번쯤인지 봐요","mis":"M2-2-u3-X16"},{"t":"몇 부분으로 나누어 어림한 뒤 더해요","mis":"M2-2-u3-X16"}],"explanation":["세어 어림은 같은 간격이 몇 개인지 세는 방법이에요.","약 2 m 간격이 5개면 약 10 m예요.","기준 삼아 어림·나누어 어림과는 다른 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#8','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'essay','teacher','운동장의 짧은 쪽 길이를 어림하는 방법을 두 가지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C8","difficulty":4,"kind":"essay","stem":"운동장의 짧은 쪽 길이를 어림하는 방법을 두 가지 설명해 보세요.","answer_guide":{"answer":"예: 축구 골대의 긴 쪽 약 5 m를 기준 삼아 몇 번쯤인지 본다. 끝~골대, 골대, 골대~끝으로 나누어 부분마다 어림한 뒤 모두 더한다.","scoring_points":["기준 삼아 어림하는 방법을 썼는가","나누어 어림하거나 세어 어림하는 방법을 썼는가","어림한 길이에 「약」을 붙이거나 자로 확인한다고 썼는가"]},"explanation":["아는 길이(5 m)를 기준 삼아 몇 번쯤인지 봐요.","몇 부분으로 나누어 어림하고 더해요.","같은 간격이 몇 개인지 세어 어림해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#9','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'essay','teacher','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 구하고, 약 8 m가 아닌 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C8","difficulty":4,"kind":"essay","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 구하고, 약 8 m가 아닌 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 8명 사이의 간격은 7개이다. 약 1 m씩 7번이므로 약 7 m이다. 맨 앞 학생 앞에는 간격이 없어서 간격의 수가 사람 수보다 하나 적다.","scoring_points":["간격이 7개라고 썼는가","약 7 m라고 구했는가","간격 수가 사람 수보다 하나 적은 까닭을 썼는가"]},"explanation":["8명 사이의 간격을 세어요.","간격은 7개라 약 7 m예요.","사람 수와 간격 수는 달라요."],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#10','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'mc','auto','약 25 m인 운동장의 짧은 쪽을 따라 약 5 m마다 깃발을 꽂아요. 처음과 끝에도 꽂으면 깃발은 몇 개 필요한가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":10,"concept":"M2-2-u3-C8","difficulty":4,"kind":"mc","stem":"약 25 m인 운동장의 짧은 쪽을 따라 약 5 m마다 깃발을 꽂아요. 처음과 끝에도 꽂으면 깃발은 몇 개 필요한가요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M2-2-u3-X15"},{"t":"4개","mis":"M2-2-u3-X15"}],"explanation":["약 25 m에 약 5 m 간격은 5개예요.","처음과 끝에도 꽂으면 깃발은 간격보다 하나 많아요.","그래서 5 + 1 = 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#1','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C1',1,'sa','auto','200 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"200 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","200 cm는 100 cm가 2번이에요.","그래서 200 cm = 2 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["2"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#2','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C1',1,'mc','auto','3 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"3 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번이에요.","그래서 3 m = 300 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"300 cm","correct":true},{"t":"30 cm","mis":"M2-2-u3-X01"},{"t":"3000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#3','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',1,'sa','auto','1 m 45 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"1 m 45 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["1 m는 100 cm예요.","100 cm와 45 cm를 모으면 145 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["145"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#4','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',1,'sa','auto','책장의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"책장의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 127이니 127 cm예요.","127 cm는 1 m 27 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["127"],"asset":{"type":"tape","len":127,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#5','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',1,'mc','auto','3 m 25 cm + 1 m 30 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 25 cm + 1 m 30 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 1 = 4.","cm는 cm끼리 더해요 — 25 + 30 = 55.","그래서 3 m 25 cm + 1 m 30 cm = 4 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"4 m 55 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"5 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#6','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',1,'mc','auto','4 m 58 cm − 2 m 25 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"4 m 58 cm − 2 m 25 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 2 = 2.","cm는 cm끼리 빼요 — 58 − 25 = 33.","그래서 4 m 58 cm − 2 m 25 cm = 2 m 33 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"2 m 33 cm","correct":true},{"t":"6 m 83 cm","mis":"M2-2-u3-X10"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#7','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C7',1,'mc','auto','자로 재지 않고 칠판의 긴 쪽을 3 m쯤으로 짐작했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"자로 재지 않고 칠판의 긴 쪽을 3 m쯤으로 짐작했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 3 m","correct":true},{"t":"3 m","mis":"M2-2-u3-X12"},{"t":"약 3 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 것은 어림이에요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 3 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#8','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C3',1,'mc','auto','연필의 길이는 약 17 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"연필의 길이는 약 17 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["연필은 손에 쥘 만큼 짧아요.","약 17 m는 교실보다 길어요.","그래서 약 17 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#9','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',2,'mc','auto','248 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"248 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["248 cm는 200 cm와 48 cm예요.","200 cm는 2 m예요.","그래서 248 cm = 2 m 48 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"2 m 48 cm","correct":true},{"t":"24 m 8 cm","mis":"M2-2-u3-X03"},{"t":"2 m 4 cm","mis":"M2-2-u3-X11"},{"t":"48 m 2 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#10','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',2,'mc','auto','책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 130이니 130 cm예요.","130 cm = 100 cm + 30 cm = 1 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"1 m 30 cm","correct":true},{"t":"13 m","mis":"M2-2-u3-X03"},{"t":"1 m 31 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":130,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#11','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 3 = 8.","cm는 cm끼리 더해요 — 24 + 51 = 75.","그래서 5 m 24 cm + 3 m 51 cm = 8 m 75 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"8 m 75 cm","correct":true},{"t":"2 m 27 cm","mis":"M2-2-u3-X10"},{"t":"9 m 75 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[5,24],"b":[3,51],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#12','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',2,'mc','auto','4 m 86 cm인 색 테이프에서 2 m 53 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"4 m 86 cm인 색 테이프에서 2 m 53 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 2 = 2.","cm는 cm끼리 빼요 — 86 − 53 = 33.","그래서 4 m 86 cm − 2 m 53 cm = 2 m 33 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"2 m 33 cm","correct":true},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"},{"t":"2 m 43 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[4,86],[2,53]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#13','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#14','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 4 m는 1 m가 4번이니 2걸음씩 4번 — 2 + 2 + 2 + 2 = 8이에요.","그래서 약 8걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 8걸음","correct":true},{"t":"약 6걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#15','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',2,'mc','auto','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 8명이면 사이 간격은 7개예요.","약 1 m씩 7번이니 약 7 m예요.","사람 수만큼 8번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 7 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#16','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 2개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 2개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 2번 있어요.","5 + 5 = 10이에요.","그래서 모두 약 10 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 5 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#17','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',3,'mc','auto','탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?","explanation":["탁자의 한끝은 눈금 2, 다른 끝은 눈금 136에 있어요.","136 − 2 = 134이니 134 cm예요.","끝 눈금 136을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"134 cm","correct":true},{"t":"136 cm","mis":"M2-2-u3-X06"},{"t":"135 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":134,"label":"탁자","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#18','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 3 m 46 cm를 굴러간 뒤 5 m 2 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 3 m 46 cm를 굴러간 뒤 5 m 2 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 46 + 2 = 48.","그래서 3 m 46 cm + 5 m 2 cm = 8 m 48 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"8 m 48 cm","correct":true},{"t":"2 m 44 cm","mis":"M2-2-u3-X10"},{"t":"8 m 66 cm","mis":"M2-2-u3-X09"},{"t":"9 m 48 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#19','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 8 m 69 cm와 3 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 8 m 69 cm와 3 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 3 = 5.","cm는 cm끼리 빼요 — 69 − 4 = 65.","그래서 8 m 69 cm − 3 m 4 cm = 5 m 65 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"5 m 65 cm","correct":true},{"t":"11 m 73 cm","mis":"M2-2-u3-X10"},{"t":"5 m 29 cm","mis":"M2-2-u3-X09"},{"t":"6 m 65 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#20','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',3,'mc','auto','범고래의 몸길이는 6 m 50 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"범고래의 몸길이는 6 m 50 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?","options":[{"t":"5 m 20 cm","correct":true},{"t":"7 m 80 cm","mis":"M2-2-u3-X10"},{"t":"5 m 2 cm","mis":"M2-2-u3-X11"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 6 − 1 = 5, cm끼리 50 − 30 = 20이에요.","그래서 5 m 20 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#21','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',3,'mc','auto','조사한 동물의 몸길이를 카드에 적었어요. 바르게 적은 것은 어느 것인가요?',ARRAY['M2-2-u3-X05','M2-2-u3-X03']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"조사한 동물의 몸길이를 카드에 적었어요. 바르게 적은 것은 어느 것인가요?","options":[{"t":"가오리 — 약 2 m 40 cm","correct":true},{"t":"가오리 — 약 240","mis":"M2-2-u3-X05"},{"t":"가오리 — 약 24 m","mis":"M2-2-u3-X03"}],"explanation":["몸길이에는 단위를 꼭 붙여요.","240 cm는 2 m 40 cm예요.","약 240은 단위가 없고, 약 24 m는 열 배나 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#22','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',3,'mc','auto','울타리 한 칸은 약 2 m, 그네의 길이는 약 4 m예요. 나무에서 그네까지 울타리 세 칸, 그네, 그네에서 다른 나무까지 울타리 세 칸이에요. 두 나무 사이는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"울타리 한 칸은 약 2 m, 그네의 길이는 약 4 m예요. 나무에서 그네까지 울타리 세 칸, 그네, 그네에서 다른 나무까지 울타리 세 칸이에요. 두 나무 사이는 약 몇 m인가요?","options":[{"t":"약 16 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X14"},{"t":"약 12 m","mis":"M2-2-u3-X14"}],"explanation":["울타리 세 칸은 약 6 m예요.","6 + 4 + 6 = 16이에요.","그래서 두 나무 사이는 약 16 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#23','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',4,'essay','teacher','5 m 64 cm − 3 m 22 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"5 m 64 cm − 3 m 22 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인해 보세요.","answer_guide":{"answer":"예: m끼리 5 − 3 = 2, cm끼리 64 − 22 = 42이므로 2 m 42 cm이다. 2 m 42 cm + 3 m 22 cm = 5 m 64 cm가 되어 맞다.","scoring_points":["2 m 42 cm를 구했는가","차에 뺀 길이를 더해 확인했는가","처음 길이가 나온다고 썼는가"]},"explanation":["m는 m끼리, cm는 cm끼리 빼요.","2 m 42 cm + 3 m 22 cm = 5 m 64 cm예요.","처음 길이가 나오면 맞게 계산한 거예요."],"asset":{"type":"mcm_calc","a":[5,64],"b":[3,22],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#24','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',4,'essay','teacher','범고래(6 m 50 cm)와 바다거북(1 m 30 cm)의 몸길이를 교실 바닥에 줄자로 나타냈어요. 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"범고래(6 m 50 cm)와 바다거북(1 m 30 cm)의 몸길이를 교실 바닥에 줄자로 나타냈어요. 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 범고래가 더 길다. 6 m 50 cm − 1 m 30 cm에서 m끼리 5, cm끼리 20이므로 범고래가 5 m 20 cm 더 길다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#25','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',4,'mc','auto','바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 이은 길이는 바다악어(4 m 80 cm)보다 얼마나 짧은가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 이은 길이는 바다악어(4 m 80 cm)보다 얼마나 짧은가요?","options":[{"t":"1 m 30 cm","correct":true},{"t":"3 m 50 cm","mis":"M2-2-u3-X16"},{"t":"8 m 30 cm","mis":"M2-2-u3-X10"}],"explanation":["바다거북과 돌고래를 이으면 3 m 50 cm예요.","4 m 80 cm − 3 m 50 cm = 1 m 30 cm예요.","이은 길이만 구하면 안 돼요 — 한 번 더 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#1','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C1',1,'sa','auto','400 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"400 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","400 cm는 100 cm가 4번이에요.","그래서 400 cm = 4 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#2','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C1',1,'mc','auto','6 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"6 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","6 m는 100 cm가 6번이에요.","그래서 6 m = 600 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"600 cm","correct":true},{"t":"60 cm","mis":"M2-2-u3-X01"},{"t":"6000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#3','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',1,'sa','auto','3 m 8 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"3 m 8 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["3 m는 300 cm예요.","300 cm와 8 cm를 모으면 308 cm예요.","cm가 한 자리 수라 십의 자리에 0을 써서 308이에요 — 38이 아니에요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["308"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#4','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',1,'sa','auto','매트의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"매트의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["매트의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 146이니 146 cm예요.","146 cm는 1 m 46 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["146"],"asset":{"type":"tape","len":146,"label":"매트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#5','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',1,'mc','auto','2 m 41 cm + 4 m 36 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"2 m 41 cm + 4 m 36 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 2 + 4 = 6.","cm는 cm끼리 더해요 — 41 + 36 = 77.","그래서 2 m 41 cm + 4 m 36 cm = 6 m 77 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"6 m 77 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"7 m 77 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#6','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',1,'mc','auto','7 m 69 cm − 3 m 14 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"7 m 69 cm − 3 m 14 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 7 − 3 = 4.","cm는 cm끼리 빼요 — 69 − 14 = 55.","그래서 7 m 69 cm − 3 m 14 cm = 4 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"4 m 55 cm","correct":true},{"t":"10 m 83 cm","mis":"M2-2-u3-X10"},{"t":"5 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#7','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',1,'mc','auto','양팔을 벌린 길이로 1 m를 어림할 수 있어요. 양팔을 벌린 길이는 약 몇 m인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"양팔을 벌린 길이로 1 m를 어림할 수 있어요. 양팔을 벌린 길이는 약 몇 m인가요?","options":[{"t":"약 1 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X17"},{"t":"약 1 cm","mis":"M2-2-u3-X17"}],"explanation":["양팔을 벌린 길이는 1 m쯤이에요.","1 m를 어림하는 기준으로 써요.","그래서 약 1 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#8','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C3',1,'mc','auto','교실의 짧은 쪽의 길이는 약 7 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"교실의 짧은 쪽의 길이는 약 7 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["교실은 아주 넓어요.","약 7 cm는 손가락만큼이라 너무 짧아요.","그래서 약 7 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#9','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',2,'mc','auto','405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["405 cm는 400 cm와 5 cm예요.","400 cm는 4 m예요.","그래서 405 cm = 4 m 5 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"4 m 5 cm","correct":true},{"t":"40 m 5 cm","mis":"M2-2-u3-X03"},{"t":"4 m 50 cm","mis":"M2-2-u3-X09"},{"t":"5 m 4 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#10','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',2,'mc','auto','사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["사물함의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#11','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 1 + 5 = 6.","cm는 cm끼리 더해요 — 52 + 26 = 78.","그래서 1 m 52 cm + 5 m 26 cm = 6 m 78 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"6 m 78 cm","correct":true},{"t":"4 m 26 cm","mis":"M2-2-u3-X10"},{"t":"7 m 78 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[1,52],"b":[5,26],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#12','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',2,'mc','auto','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 88 − 26 = 62.","그래서 6 m 88 cm − 4 m 26 cm = 2 m 62 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"two"}},"options":[{"t":"2 m 62 cm","correct":true},{"t":"3 m 62 cm","mis":"M2-2-u3-X08"},{"t":"2 m 72 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#13','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#14','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 3 m는 1 m가 3번이니 3걸음씩 3번 — 3 + 3 + 3 = 9예요.","그래서 약 9걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 9걸음","correct":true},{"t":"약 6걸음","mis":"M2-2-u3-X14"},{"t":"약 3걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#15','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',2,'mc','auto','학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 5명이면 사이 간격은 4개예요.","약 1 m씩 4번이니 약 4 m예요.","사람 수만큼 5번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 4 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X15"},{"t":"약 6 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":5,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#16','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요?","explanation":["약 2 m가 5번 있어요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 모두 약 10 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 8 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#17','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',3,'mc','auto','소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요?","explanation":["소파의 한끝은 눈금 3, 다른 끝은 눈금 149에 있어요.","149 − 3 = 146이니 146 cm예요.","끝 눈금 149를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"146 cm","correct":true},{"t":"149 cm","mis":"M2-2-u3-X06"},{"t":"147 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":146,"label":"소파","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#18','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 6 m 52 cm를 굴러간 뒤 2 m 7 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 6 m 52 cm를 굴러간 뒤 2 m 7 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 6 + 2 = 8.","cm는 cm끼리 더해요 — 52 + 7 = 59.","그래서 6 m 52 cm + 2 m 7 cm = 8 m 59 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"8 m 59 cm","correct":true},{"t":"4 m 45 cm","mis":"M2-2-u3-X10"},{"t":"9 m 59 cm","mis":"M2-2-u3-X08"},{"t":"8 m 69 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#19','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 4 m 29 cm와 1 m 6 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 4 m 29 cm와 1 m 6 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 1 = 3.","cm는 cm끼리 빼요 — 29 − 6 = 23.","그래서 4 m 29 cm − 1 m 6 cm = 3 m 23 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"3 m 23 cm","correct":true},{"t":"5 m 35 cm","mis":"M2-2-u3-X10"},{"t":"4 m 23 cm","mis":"M2-2-u3-X08"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#20','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',3,'mc','auto','바다악어의 몸길이는 4 m 80 cm, 돌고래의 몸길이는 2 m 20 cm예요. 두 동물의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다악어의 몸길이는 4 m 80 cm, 돌고래의 몸길이는 2 m 20 cm예요. 두 동물의 몸길이의 차는 얼마인가요?","options":[{"t":"2 m 60 cm","correct":true},{"t":"7 m","mis":"M2-2-u3-X10"},{"t":"2 m 6 cm","mis":"M2-2-u3-X11"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 4 − 2 = 2, cm끼리 80 − 20 = 60이에요.","그래서 2 m 60 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#21','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',3,'mc','auto','바다악어는 4 m 80 cm, 백상아리는 430 cm, 돌고래는 2 m 20 cm예요. 몸길이가 가장 긴 동물은 무엇인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다악어는 4 m 80 cm, 백상아리는 430 cm, 돌고래는 2 m 20 cm예요. 몸길이가 가장 긴 동물은 무엇인가요?","options":[{"t":"바다악어","correct":true},{"t":"백상아리","mis":"M2-2-u3-X18"},{"t":"돌고래","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 480 cm, 430 cm, 220 cm예요.","480 cm가 가장 길어요.","보이는 수 430만 보면 안 돼요 — 바다악어가 가장 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#22','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',3,'mc','auto','깃발 7개가 약 5 m 간격으로 한 줄로 꽂혀 있어요. 첫 깃발에서 마지막 깃발까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"깃발 7개가 약 5 m 간격으로 한 줄로 꽂혀 있어요. 첫 깃발에서 마지막 깃발까지는 약 몇 m인가요?","options":[{"t":"약 30 m","correct":true},{"t":"약 35 m","mis":"M2-2-u3-X15"},{"t":"약 12 m","mis":"M2-2-u3-X14"}],"explanation":["깃발이 7개면 사이 간격은 6개예요.","약 5 m씩 6번이면 약 30 m예요.","깃발 수만큼 7번 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#23','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',4,'essay','teacher','11 m 35 cm + 7 m 23 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"11 m 35 cm + 7 m 23 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.","answer_guide":{"answer":"예: m는 m 아래, cm는 cm 아래에 맞추어 쓴다. cm끼리 35 + 23 = 58, m끼리 11 + 7 = 18이다. 합은 18 m 58 cm이다.","scoring_points":["같은 단위끼리 맞추어 쓴다고 했는가","cm끼리·m끼리 더했는가","18 m 58 cm라고 구했는가"]},"explanation":["같은 단위끼리 맞추어 써요.","cm끼리 58, m끼리 18이에요.","두 길이의 합은 18 m 58 cm예요."],"asset":{"type":"mcm_calc","a":[11,35],"b":[7,23],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#24','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',4,'essay','teacher','바다악어(4 m 80 cm)와 돌고래(2 m 20 cm) 가운데 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"바다악어(4 m 80 cm)와 돌고래(2 m 20 cm) 가운데 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 바다악어가 더 길다. 4 m 80 cm − 2 m 20 cm에서 m끼리 2, cm끼리 60이므로 바다악어가 2 m 60 cm 더 길다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#25','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',4,'mc','auto','돌고래(2 m 20 cm)와 바다거북(1 m 30 cm)을 이은 길이와 범고래(6 m 50 cm)의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"돌고래(2 m 20 cm)와 바다거북(1 m 30 cm)을 이은 길이와 범고래(6 m 50 cm)의 몸길이의 차는 얼마인가요?","options":[{"t":"3 m","correct":true},{"t":"3 m 50 cm","mis":"M2-2-u3-X16"},{"t":"10 m","mis":"M2-2-u3-X10"}],"explanation":["돌고래와 바다거북을 이으면 3 m 50 cm예요.","6 m 50 cm − 3 m 50 cm = 3 m예요.","그래서 차는 3 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#1','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C1',1,'sa','auto','500 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"500 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","500 cm는 100 cm가 5번이에요.","그래서 500 cm = 5 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["5"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#2','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C1',1,'mc','auto','8 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"8 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","8 m는 100 cm가 8번이에요.","그래서 8 m = 800 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"800 cm","correct":true},{"t":"80 cm","mis":"M2-2-u3-X01"},{"t":"8000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#3','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',1,'sa','auto','2 m 70 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"2 m 70 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["2 m는 200 cm예요.","200 cm와 70 cm를 모으면 270 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["270"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#4','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',1,'sa','auto','탁자의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"탁자의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["탁자의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 118이니 118 cm예요.","118 cm는 1 m 18 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["118"],"asset":{"type":"tape","len":118,"label":"탁자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#5','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',1,'mc','auto','5 m 12 cm + 2 m 53 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"5 m 12 cm + 2 m 53 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 2 = 7.","cm는 cm끼리 더해요 — 12 + 53 = 65.","그래서 5 m 12 cm + 2 m 53 cm = 7 m 65 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"7 m 65 cm","correct":true},{"t":"3 m 41 cm","mis":"M2-2-u3-X10"},{"t":"8 m 65 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#6','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',1,'mc','auto','6 m 87 cm − 5 m 42 cm는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"6 m 87 cm − 5 m 42 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 5 = 1.","cm는 cm끼리 빼요 — 87 − 42 = 45.","그래서 6 m 87 cm − 5 m 42 cm = 1 m 45 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"1 m 45 cm","correct":true},{"t":"2 m 45 cm","mis":"M2-2-u3-X08"},{"t":"1 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#7','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C7',1,'mc','auto','교실 문의 높이를 알맞게 어림한 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"교실 문의 높이를 알맞게 어림한 것은 어느 것인가요?","options":[{"t":"약 2 m","correct":true},{"t":"약 2 cm","mis":"M2-2-u3-X17"},{"t":"약 20 m","mis":"M2-2-u3-X17"}],"explanation":["교실 문은 어른 키보다 조금 높아요.","1 m의 두 배쯤이에요.","그래서 약 2 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#8','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C3',1,'mc','auto','수학책의 긴 쪽의 길이는 약 27 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"수학책의 긴 쪽의 길이는 약 27 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["수학책은 책상 위에 놓을 만큼 작아요.","약 27 m는 운동장 반쯤이에요.","그래서 약 27 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#9','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',2,'mc','auto','352 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"352 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["352 cm는 300 cm와 52 cm예요.","300 cm는 3 m예요.","그래서 352 cm = 3 m 52 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"3 m 52 cm","correct":true},{"t":"35 m 2 cm","mis":"M2-2-u3-X03"},{"t":"3 m 5 cm","mis":"M2-2-u3-X11"},{"t":"52 m 3 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#10','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',2,'mc','auto','현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["현수막의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 207이니 207 cm예요.","207 cm = 200 cm + 7 cm = 2 m 7 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"2 m 7 cm","correct":true},{"t":"20 m 7 cm","mis":"M2-2-u3-X03"},{"t":"2 m 8 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":207,"label":"현수막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#11','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 6 + 2 = 8.","cm는 cm끼리 더해요 — 14 + 71 = 85.","그래서 6 m 14 cm + 2 m 71 cm = 8 m 85 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"8 m 85 cm","correct":true},{"t":"4 m 57 cm","mis":"M2-2-u3-X10"},{"t":"9 m 85 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[6,14],"b":[2,71],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#12','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',2,'mc','auto','5 m 64 cm인 색 테이프에서 3 m 22 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"5 m 64 cm인 색 테이프에서 3 m 22 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 5 − 3 = 2.","cm는 cm끼리 빼요 — 64 − 22 = 42.","그래서 5 m 64 cm − 3 m 22 cm = 2 m 42 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"2 m 42 cm","correct":true},{"t":"8 m 86 cm","mis":"M2-2-u3-X10"},{"t":"3 m 42 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[5,64],[3,22]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#13','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#14','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 6 m는 1 m가 6번이니 2걸음씩 6번 — 2 + 2 + 2 + 2 + 2 + 2 = 12예요.","그래서 약 12걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 12걸음","correct":true},{"t":"약 8걸음","mis":"M2-2-u3-X14"},{"t":"약 6걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#15','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',2,'mc','auto','학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 4명이면 사이 간격은 3개예요.","약 2 m씩 3번이니 약 6 m예요.","사람 수만큼 4번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 6 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":4,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#16','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 3번 있어요.","5 + 5 + 5 = 15예요.","그래서 모두 약 15 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 15 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X14"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#17','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',3,'mc','auto','밧줄의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 밧줄의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"밧줄의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 밧줄의 길이는 몇 cm인가요?","explanation":["밧줄의 한끝은 눈금 3, 다른 끝은 눈금 128에 있어요.","128 − 3 = 125이니 125 cm예요.","끝 눈금 128을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"125 cm","correct":true},{"t":"128 cm","mis":"M2-2-u3-X06"},{"t":"126 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":125,"label":"밧줄","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#18','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 3 m 40 cm를 굴러간 뒤 4 m 9 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 3 m 40 cm를 굴러간 뒤 4 m 9 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 4 = 7.","cm는 cm끼리 더해요 — 40 + 9 = 49.","그래서 3 m 40 cm + 4 m 9 cm = 7 m 49 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"7 m 49 cm","correct":true},{"t":"1 m 31 cm","mis":"M2-2-u3-X10"},{"t":"8 m 49 cm","mis":"M2-2-u3-X08"},{"t":"7 m 59 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#19','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 7 m 85 cm와 2 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 7 m 85 cm와 2 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 7 − 2 = 5.","cm는 cm끼리 빼요 — 85 − 4 = 81.","그래서 7 m 85 cm − 2 m 4 cm = 5 m 81 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"5 m 81 cm","correct":true},{"t":"9 m 89 cm","mis":"M2-2-u3-X10"},{"t":"5 m 45 cm","mis":"M2-2-u3-X09"},{"t":"6 m 81 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#20','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',3,'mc','auto','바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)의 몸길이를 교실 바닥에 이어서 나타냈어요. 이은 길이는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)의 몸길이를 교실 바닥에 이어서 나타냈어요. 이은 길이는 모두 얼마인가요?","options":[{"t":"3 m 50 cm","correct":true},{"t":"90 cm","mis":"M2-2-u3-X10"},{"t":"3 m 5 cm","mis":"M2-2-u3-X11"}],"explanation":["이은 길이는 두 몸길이의 합이에요.","m끼리 1 + 2 = 3, cm끼리 30 + 20 = 50이에요.","그래서 3 m 50 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#21','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',3,'mc','auto','내 키는 1 m 30 cm예요. 바다거북은 130 cm, 바다표범은 1 m 80 cm, 돌고래는 220 cm예요. 내 키와 몸길이가 같은 동물은 무엇인가요?',ARRAY['M2-2-u3-X18']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"내 키는 1 m 30 cm예요. 바다거북은 130 cm, 바다표범은 1 m 80 cm, 돌고래는 220 cm예요. 내 키와 몸길이가 같은 동물은 무엇인가요?","options":[{"t":"바다거북","correct":true},{"t":"바다표범","mis":"M2-2-u3-X18"},{"t":"돌고래","mis":"M2-2-u3-X18"}],"explanation":["1 m 30 cm는 130 cm예요.","바다거북의 몸길이 130 cm와 같아요.","그래서 바다거북이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#22','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',3,'mc','auto','약 10 m인 복도를 약 2 m씩 나누었어요. 모두 몇 칸이 되나요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"약 10 m인 복도를 약 2 m씩 나누었어요. 모두 몇 칸이 되나요?","options":[{"t":"5칸","correct":true},{"t":"8칸","mis":"M2-2-u3-X14"},{"t":"20칸","mis":"M2-2-u3-X14"}],"explanation":["약 2 m가 몇 번이면 약 10 m인지 찾아요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 5칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#23','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',4,'essay','teacher','2 m 24 cm + 7 m 5 cm를 9 m 74 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"2 m 24 cm + 7 m 5 cm를 9 m 74 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 7 m 5 cm의 5를 50처럼 더해 24 + 50 = 74로 계산했다. cm끼리 24 + 5 = 29이므로 바른 답은 9 m 29 cm이다.","scoring_points":["5를 50으로 본 잘못을 찾았는가","cm끼리 24 + 5 = 29를 구했는가","9 m 29 cm라고 바르게 썼는가"]},"explanation":["7 m 5 cm의 cm는 5예요.","cm끼리 24 + 5 = 29예요.","바른 답은 9 m 29 cm예요."],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"both","said":[9,74]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#24','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',4,'essay','teacher','바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 바닥에 이어서 나타내면 길이가 얼마인지 구하고, 그 길이가 범고래(6 m 50 cm)보다 얼마나 짧은지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 바닥에 이어서 나타내면 길이가 얼마인지 구하고, 그 길이가 범고래(6 m 50 cm)보다 얼마나 짧은지 설명해 보세요.","answer_guide":{"answer":"예: 1 m 30 cm + 2 m 20 cm = 3 m 50 cm이다. 6 m 50 cm − 3 m 50 cm = 3 m이므로 범고래보다 3 m 짧다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#25','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',4,'mc','auto','줄넘기 줄 2 m 45 cm에서 1 m 20 cm를 잘라 쓰고, 남은 줄에 1 m 30 cm를 이었어요. 줄의 길이는 얼마가 되었나요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"줄넘기 줄 2 m 45 cm에서 1 m 20 cm를 잘라 쓰고, 남은 줄에 1 m 30 cm를 이었어요. 줄의 길이는 얼마가 되었나요?","options":[{"t":"2 m 55 cm","correct":true},{"t":"1 m 25 cm","mis":"M2-2-u3-X16"},{"t":"4 m 95 cm","mis":"M2-2-u3-X10"}],"explanation":["잘라 쓰고 남은 줄은 2 m 45 cm − 1 m 20 cm = 1 m 25 cm예요.","1 m 25 cm + 1 m 30 cm = 2 m 55 cm예요.","빼고 나서 더해요 — 모두 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#1','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C1',1,'sa','auto','700 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"700 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","700 cm는 100 cm가 7번이에요.","그래서 700 cm = 7 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["7"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#2','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C1',1,'mc','auto','9 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"9 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","9 m는 100 cm가 9번이에요.","그래서 9 m = 900 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"900 cm","correct":true},{"t":"90 cm","mis":"M2-2-u3-X01"},{"t":"9000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#3','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',1,'sa','auto','6 m 15 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"6 m 15 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["6 m는 600 cm예요.","600 cm와 15 cm를 모으면 615 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["615"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#4','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',1,'sa','auto','현수막의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"현수막의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["현수막의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 236이니 236 cm예요.","236 cm는 2 m 36 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["236"],"asset":{"type":"tape","len":236,"label":"현수막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#5','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',1,'mc','auto','1 m 64 cm + 6 m 23 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"1 m 64 cm + 6 m 23 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 1 + 6 = 7.","cm는 cm끼리 더해요 — 64 + 23 = 87.","그래서 1 m 64 cm + 6 m 23 cm = 7 m 87 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"7 m 87 cm","correct":true},{"t":"5 m 41 cm","mis":"M2-2-u3-X10"},{"t":"8 m 87 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#6','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',1,'mc','auto','8 m 53 cm − 2 m 31 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"8 m 53 cm − 2 m 31 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 2 = 6.","cm는 cm끼리 빼요 — 53 − 31 = 22.","그래서 8 m 53 cm − 2 m 31 cm = 6 m 22 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"6 m 22 cm","correct":true},{"t":"10 m 84 cm","mis":"M2-2-u3-X10"},{"t":"7 m 22 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#7','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C7',1,'mc','auto','바다악어의 몸길이를 알맞게 어림한 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"바다악어의 몸길이를 알맞게 어림한 것은 어느 것인가요?","options":[{"t":"약 3 m","correct":true},{"t":"약 3 cm","mis":"M2-2-u3-X17"},{"t":"약 300 m","mis":"M2-2-u3-X17"}],"explanation":["바다악어는 사람 키보다 훨씬 길어요.","양팔을 세 번쯤 벌린 길이예요.","그래서 약 3 m가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#8','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C3',1,'mc','auto','축구 골대의 긴 쪽의 길이는 약 5 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"축구 골대의 긴 쪽의 길이는 약 5 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["축구 골대는 사람 여러 명이 설 만큼 길어요.","약 5 cm는 지우개만큼이라 너무 짧아요.","그래서 약 5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#9','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',2,'mc','auto','709 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"709 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["709 cm는 700 cm와 9 cm예요.","700 cm는 7 m예요.","그래서 709 cm = 7 m 9 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"7 m 9 cm","correct":true},{"t":"70 m 9 cm","mis":"M2-2-u3-X03"},{"t":"7 m 90 cm","mis":"M2-2-u3-X09"},{"t":"9 m 7 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#10','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',2,'mc','auto','커튼의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"커튼의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["커튼의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 185이니 185 cm예요.","185 cm = 100 cm + 85 cm = 1 m 85 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"1 m 85 cm","correct":true},{"t":"18 m 5 cm","mis":"M2-2-u3-X03"},{"t":"1 m 86 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":185,"label":"커튼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#11','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 3 = 6.","cm는 cm끼리 더해요 — 8 + 61 = 69.","그래서 3 m 8 cm + 3 m 61 cm = 6 m 69 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"6 m 69 cm","correct":true},{"t":"7 m 69 cm","mis":"M2-2-u3-X08"},{"t":"6 m 79 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[3,8],"b":[3,61],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#12','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',2,'mc','auto','길이가 9 m 95 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 6 m 40 cm일 때 다른 도막의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"길이가 9 m 95 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 6 m 40 cm일 때 다른 도막의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 9 − 6 = 3.","cm는 cm끼리 빼요 — 95 − 40 = 55.","그래서 9 m 95 cm − 6 m 40 cm = 3 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"two"}},"options":[{"t":"3 m 55 cm","correct":true},{"t":"4 m 55 cm","mis":"M2-2-u3-X08"},{"t":"3 m 65 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#13','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#14','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 5 m는 1 m가 5번이니 3걸음씩 5번 — 3 + 3 + 3 + 3 + 3 = 15예요.","그래서 약 15걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 15걸음","correct":true},{"t":"약 8걸음","mis":"M2-2-u3-X14"},{"t":"약 5걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#15','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',2,'mc','auto','학생 7명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 7명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 7명이면 사이 간격은 6개예요.","약 1 m씩 6번이니 약 6 m예요.","사람 수만큼 7번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 6 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X15"},{"t":"약 8 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":7,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#16','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 3 m인 간격이 3개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 3 m인 간격이 3개 있어요. 모두 약 몇 m인가요?","explanation":["약 3 m가 3번 있어요.","3 + 3 + 3 = 9예요.","그래서 모두 약 9 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 9 m","correct":true},{"t":"약 6 m","mis":"M2-2-u3-X14"},{"t":"약 12 m","mis":"M2-2-u3-X14"}],"asset":{"type":"est_row","seg":3,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#17','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',3,'mc','auto','매트의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 매트의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"매트의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 매트의 길이는 몇 cm인가요?","explanation":["매트의 한끝은 눈금 2, 다른 끝은 눈금 215에 있어요.","215 − 2 = 213이니 213 cm예요.","끝 눈금 215를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"213 cm","correct":true},{"t":"215 cm","mis":"M2-2-u3-X06"},{"t":"214 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":213,"label":"매트","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#18','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 5 m 8 cm를 굴러간 뒤 1 m 61 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 5 m 8 cm를 굴러간 뒤 1 m 61 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 1 = 6.","cm는 cm끼리 더해요 — 8 + 61 = 69.","그래서 5 m 8 cm + 1 m 61 cm = 6 m 69 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"6 m 69 cm","correct":true},{"t":"4 m 53 cm","mis":"M2-2-u3-X10"},{"t":"7 m 69 cm","mis":"M2-2-u3-X08"},{"t":"6 m 79 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#19','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 6 m 57 cm와 3 m 2 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 6 m 57 cm와 3 m 2 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 3 = 3.","cm는 cm끼리 빼요 — 57 − 2 = 55.","그래서 6 m 57 cm − 3 m 2 cm = 3 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"3 m 55 cm","correct":true},{"t":"9 m 59 cm","mis":"M2-2-u3-X10"},{"t":"3 m 37 cm","mis":"M2-2-u3-X09"},{"t":"4 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#20','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',3,'mc','auto','백상아리의 몸길이는 4 m 30 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"백상아리의 몸길이는 4 m 30 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?","options":[{"t":"3 m","correct":true},{"t":"5 m 60 cm","mis":"M2-2-u3-X10"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 4 − 1 = 3, cm끼리 30 − 30 = 0이에요.","그래서 3 m예요 — cm 자리가 0이면 m만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#21','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범의 몸길이 1 m 80 cm를 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X02']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범의 몸길이 1 m 80 cm를 cm로 나타내면 얼마인가요?","options":[{"t":"180 cm","correct":true},{"t":"18 cm","mis":"M2-2-u3-X11"},{"t":"108 cm","mis":"M2-2-u3-X02"}],"explanation":["1 m는 100 cm예요.","100 cm와 80 cm를 모으면 180 cm예요.","80의 0을 떼거나 자리를 바꾸면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#22','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',3,'mc','auto','정문에서 운동장까지 약 30 m, 운동장의 짧은 쪽은 약 25 m예요. 정문에서 운동장을 가로질러 반대쪽 끝까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"정문에서 운동장까지 약 30 m, 운동장의 짧은 쪽은 약 25 m예요. 정문에서 운동장을 가로질러 반대쪽 끝까지는 약 몇 m인가요?","options":[{"t":"약 55 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X10"},{"t":"약 45 m","mis":"M2-2-u3-X14"}],"explanation":["두 부분으로 나누어 어림한 길이를 더해요.","30 + 25 = 55예요.","그래서 약 55 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#23','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',4,'essay','teacher','색 테이프 3 m 75 cm에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이를 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"색 테이프 3 m 75 cm에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이를 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 남은 길이는 처음 길이에서 쓴 길이를 뺀다. 3 m 75 cm − 1 m 52 cm에서 m끼리 2, cm끼리 23이므로 2 m 23 cm이다.","scoring_points":["뺄셈으로 구해야 함을 썼는가","m끼리·cm끼리 뺐는가","2 m 23 cm라고 구했는가"]},"explanation":["남은 길이는 차로 구해요.","m끼리 3 − 1 = 2, cm끼리 75 − 52 = 23이에요.","남은 색 테이프는 2 m 23 cm예요."],"asset":{"type":"mbar","parts":[[3,75],[1,52]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#24','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',4,'essay','teacher','내 키는 1 m 20 cm예요. 백상아리(4 m 30 cm)는 내 키보다 얼마나 더 긴지 구하고, 동물 카드에 어떻게 적으면 좋을지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"내 키는 1 m 20 cm예요. 백상아리(4 m 30 cm)는 내 키보다 얼마나 더 긴지 구하고, 동물 카드에 어떻게 적으면 좋을지 써 보세요.","answer_guide":{"answer":"예: 4 m 30 cm − 1 m 20 cm = 3 m 10 cm이다. 카드에는 「백상아리 — 약 4 m 30 cm, 내 키보다 3 m 10 cm 더 길다」처럼 단위를 붙여 적는다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#25','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',4,'mc','auto','8 m 76 cm인 막대에서 2 m 34 cm짜리 도막을 두 개 잘라 냈어요. 남은 막대의 길이는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X09']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"8 m 76 cm인 막대에서 2 m 34 cm짜리 도막을 두 개 잘라 냈어요. 남은 막대의 길이는 얼마인가요?","options":[{"t":"4 m 8 cm","correct":true},{"t":"6 m 42 cm","mis":"M2-2-u3-X16"},{"t":"4 m 80 cm","mis":"M2-2-u3-X09"}],"explanation":["한 도막을 잘라 내면 8 m 76 cm − 2 m 34 cm = 6 m 42 cm예요.","한 도막을 더 잘라 내면 6 m 42 cm − 2 m 34 cm = 4 m 8 cm예요.","cm가 8이라 4 m 80 cm로 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
